import collections
import subprocess

def lines(cmd):
    return subprocess.check_output(cmd, text=True).splitlines()

dev = 'dev'
nxt = 'next'
existing_dev_dirs = set(lines(['git','ls-tree','-d','--name-only',dev]))
existing_next_dirs = set(lines(['git','ls-tree','-d','--name-only',nxt]))
ignored_top={'.codex','.conduct','.cursor','.factory','.github','.tmp','_conduct','docs','scripts'}
scope=sorted((existing_dev_dirs & existing_next_dirs)-ignored_top)
raw=lines(['git','diff','--name-status',f'{dev}..{nxt}','--',*scope])
records=[]
for line in raw:
    cols=line.split('\t'); status=cols[0]; path=cols[-1]
    if '/.conduct/' in path or path.startswith('.conduct/') or path.startswith('_conduct/'):
        continue
    top=path.split('/')[0]
    if top not in scope: continue
    group=top
    if top=='packages':
        parts=path.split('/'); group='/'.join(parts[:2]) if len(parts)>1 else path
    records.append((group,status,path))
grouped=collections.defaultdict(list)
for g,s,p in records: grouped[g].append((s,p))
print('DIVERGENCE',subprocess.check_output(['git','rev-list','--left-right','--count',f'{dev}...{nxt}'],text=True).strip())
print('COMMON_TOP',*scope)
print('NEXT_ONLY_TOP',*sorted(existing_next_dirs-existing_dev_dirs-ignored_top))
for g in sorted(grouped):
    c=collections.Counter(s[0] for s,_ in grouped[g])
    print(f'GROUP\t{g}\t{len(grouped[g])}\t'+','.join(f'{k}:{c[k]}' for k in 'AMDR' if c[k]))
    for s,p in grouped[g]: print(f'  {s}\t{p}')
PY","workdir":"/Users/serro/Documents/dev/n/superfunctions","yield_time_ms":30000,"max_output_tokens":30000});
