import { isAbsolute } from 'node:path';
import { pathToFileURL } from 'node:url';
import type { SuperConsole } from './super-console.js';

const INSTALLATION = Symbol.for('superfunctions.superconsole.installation.v1');
const LOADER = Symbol.for('superfunctions.superconsole.installation-loader.v1');

type InstallationGlobal = typeof globalThis & { [INSTALLATION]?: SuperConsole; [LOADER]?: Promise<SuperConsole> };

/** Configure one process-local, explicitly composed self-hosted installation. */
export function configureSuperConsole(console: SuperConsole): SuperConsole {
  if ((globalThis as InstallationGlobal)[INSTALLATION]) {
    throw new Error('Super Console is already configured for this process. Refusing to replace the active installation.');
  }
  (globalThis as InstallationGlobal)[INSTALLATION] = console;
  return console;
}

export function getSuperConsole(): SuperConsole | undefined {
  return (globalThis as InstallationGlobal)[INSTALLATION];
}

export function requireSuperConsole(): SuperConsole {
  const console = getSuperConsole();
  if (!console) {
    throw new Error('Super Console is not configured. Call configureSuperConsole(createSuperConsole(...)) during server startup.');
  }
  return console;
}

export function clearSuperConsoleForTesting(): void {
  delete (globalThis as InstallationGlobal)[INSTALLATION];
  delete (globalThis as InstallationGlobal)[LOADER];
}

/** Resolve only local installation modules; package/http/data URLs are rejected. */
export function resolveSuperConsoleInstallationUrl(specifier: string): string {
  const normalized = specifier.trim();
  if (!normalized) throw new Error('SUPERCONSOLE_INSTALLATION must not be empty.');
  if (normalized.startsWith('file://')) {
    try {
      const url = new URL(normalized);
      if (url.protocol !== 'file:') throw new Error();
      return url.href;
    } catch {
      throw new Error('SUPERCONSOLE_INSTALLATION contains an invalid file URL.');
    }
  }
  if (!isAbsolute(normalized)) {
    throw new Error('SUPERCONSOLE_INSTALLATION must be an absolute filesystem path or file URL.');
  }
  return pathToFileURL(normalized).href;
}

/**
 * Load an explicitly configured installation module once. The module must be an
 * absolute file URL/path permitted by the server deployment and export either
 * `superConsole`, `default`, or `createSuperConsoleInstallation`.
 */
export async function loadSuperConsoleInstallation(specifier: string): Promise<SuperConsole> {
  const globals = globalThis as InstallationGlobal;
  if (globals[INSTALLATION]) return globals[INSTALLATION];
  globals[LOADER] ??= (async () => {
    const importUrl = resolveSuperConsoleInstallationUrl(specifier);
    const module = await import(/* @vite-ignore */ importUrl) as {
      default?: SuperConsole;
      superConsole?: SuperConsole;
      createSuperConsoleInstallation?: () => SuperConsole | Promise<SuperConsole>;
    };
    const candidate = module.createSuperConsoleInstallation
      ? await module.createSuperConsoleInstallation()
      : module.superConsole ?? module.default;
    if (!candidate || typeof candidate.handle !== 'function') {
      throw new Error('The Super Console installation module did not export a composed SuperConsole instance.');
    }
    return configureSuperConsole(candidate);
  })();
  return globals[LOADER];
}
import type {
  AdminActor,
  AdminAuditEvent,
  AdminCapabilityAdapter,
  AdminConfirmationVerifier,
  AdminIdempotencyStore,
  AdminOperationContext,
  AdminPolicyEvaluator,
  AdminScope,
  AdminAuditSink,
} from '@superfunctions/admin';

export interface SuperConsoleScopeOption {
  id: string;
  name: string;
  slug?: string;
}

export interface SuperConsoleContextOptions {
  installation?: SuperConsoleScopeOption;
  organization?: SuperConsoleScopeOption;
  workspace?: SuperConsoleScopeOption;
  project?: SuperConsoleScopeOption;
  environment?: SuperConsoleScopeOption;
  installations?: readonly SuperConsoleScopeOption[];
  organizations?: readonly SuperConsoleScopeOption[];
  workspaces?: readonly SuperConsoleScopeOption[];
  projects?: readonly SuperConsoleScopeOption[];
  environments?: readonly SuperConsoleScopeOption[];
}

export interface SuperConsolePrincipal {
  actor: AdminActor;
  displayName: string;
  email?: string;
  avatarUrl?: string;
  role: string;
  defaultScope: AdminScope;
  contextOptions?: SuperConsoleContextOptions;
  authentication?: Readonly<{
    sessionId?: string;
    type?: string;
    methods?: readonly string[];
    /** Exact provider-defined CSRF cookie selected for this request/runtime. */
    csrfCookieName?: string;
    /** Exact provider-defined CSRF request header. */
    csrfHeaderName?: string;
  }>;
}

export interface SuperConsoleSignInResult {
  principal: SuperConsolePrincipal;
  headers?: HeadersInit;
}

export interface SuperConsoleSignOutResult {
  headers?: HeadersInit;
}

export interface SuperConsoleOperatorAuth {
  authenticate(request: Request): Promise<SuperConsolePrincipal | null>;
  authorizeScope(input: {
    principal: SuperConsolePrincipal;
    requested: AdminScope;
    request: Request;
  }): Promise<AdminScope | null>;
  /** Required at startup whenever an enabled operation can mutate state. */
  authorizeMutation?(input: {
    principal: SuperConsolePrincipal;
    request: Request;
  }): Promise<void>;
  signIn?(input: { email: string; password: string; request: Request }): Promise<SuperConsoleSignInResult>;
  completeTwoFactor?(input: { challengeId: string; code: string; request: Request }): Promise<SuperConsoleSignInResult>;
  signOut?(input: { principal: SuperConsolePrincipal | null; request: Request }): Promise<SuperConsoleSignOutResult>;
  /** Optionally translate provider-owned errors into a safe HTTP response. */
  mapError?(error: unknown): Response | undefined;
}

export interface SuperConsoleShellPolicy {
  authorize(input: {
    surface: 'registry' | 'overview' | 'api' | 'mcp' | 'settings' | 'audit' | 'search';
    principal: SuperConsolePrincipal;
    context: AdminOperationContext;
  }): Promise<boolean> | boolean;
}

export interface SuperConsoleSearchResult {
  id: string;
  title: string;
  description?: string;
  moduleId: string;
  resource?: string;
  href: string;
  status?: string;
  updatedAt?: string;
}

export interface SuperConsoleSearchService {
  /** Inject a provider-neutral scoped query service. */
  search(input: {
    query: string;
    limit: number;
    cursor?: string;
    context: AdminOperationContext;
  }): Promise<{ results: readonly SuperConsoleSearchResult[]; total?: number; nextCursor?: string }>;
  /** Permission enforced before the query service is called. */
  permission: string;
}

export interface SuperConsoleAuditQuery {
  /** Inject an audit-store-backed query. */
  list(input: {
    cursor?: string;
    limit: number;
    filters: Readonly<Record<string, string>>;
    context: AdminOperationContext;
  }): Promise<{ events: readonly AdminAuditEvent[]; total?: number; nextCursor?: string }>;
  /** Permission enforced before the audit query service is called. */
  permission: string;
}

export interface SuperConsoleOverviewService {
  read(input: { context: AdminOperationContext }): Promise<{
    metrics?: readonly Record<string, unknown>[];
    alerts?: readonly Record<string, unknown>[];
    activity?: readonly Record<string, unknown>[];
    health?: readonly Record<string, unknown>[];
  }>;
  permission?: string;
}

export interface SuperConsoleSettingsService {
  read(input: { context: AdminOperationContext }): Promise<{
    policies?: readonly Record<string, unknown>[];
    retention?: readonly Record<string, unknown>[];
  }>;
  permission?: string;
  /** A function-owned admin operation; transport mutations always use the dispatcher. */
  updatePolicyOperationId?: string;
}

export interface SuperConsoleOptions {
  adapters: readonly AdminCapabilityAdapter[];
  enabledModules: readonly string[];
  auth: SuperConsoleOperatorAuth;
  audit?: AdminAuditSink;
