export class ModuleSelectionError extends Error {
  readonly code = 'SUPERCONSOLE_INVALID_MODULE_SELECTION';

  constructor(message: string, readonly details: Record<string, unknown>) {
    super(message);
    this.name = 'ModuleSelectionError';
  }
}

export function parseModuleSelection(
  value: string | readonly string[] | undefined,
  manifests: readonly AdminCapabilityManifest[],
): string[] {
  if (value === undefined) {
    throw new ModuleSelectionError('Super Console requires an explicit module selection; use [] for a shell-only installation.', {
      received: 'undefined',
    });
  }

  const catalog = createConsoleModuleCatalog(manifests);
  const byId = new Map(catalog.map((entry) => [entry.id, entry]));
  const candidates = (typeof value === 'string' ? value.split(',') : value)
    .map((candidate) => candidate.trim().toLowerCase())
    .filter(Boolean);
  const unknown = [...new Set(candidates.filter((candidate) => !byId.has(candidate)))];
  if (unknown.length > 0) {
    throw new ModuleSelectionError('The module selection contains modules without supplied administration manifests.', {
      unknown,
      available: [...byId.keys()].sort(),
    });
  }

  const unavailable = candidates.filter((candidate) => byId.get(candidate)?.availability === 'unavailable');
  if (unavailable.length > 0) {
    throw new ModuleSelectionError('The module selection contains modules without a domain-backed administration service.', {
      unavailable: [...new Set(unavailable)],
    });
  }

  const folded = candidates.filter((candidate) => byId.get(candidate)?.availability === 'folded');
  if (folded.length > 0) {
    throw new ModuleSelectionError('Folded modules are provided by their owner and cannot be selected independently.', {
      folded: [...new Set(folded)],
      owners: folded.map((moduleId) => ({ moduleId, ownerId: byId.get(moduleId)?.owner?.moduleId })),
    });
  }

  const selected = [...new Set(candidates)];
  const selectedSet = new Set(selected);
  const missingOwners = selected.flatMap((moduleId) => {
    const ownerId = byId.get(moduleId)?.owner?.moduleId;
    return ownerId && !selectedSet.has(ownerId) ? [{ moduleId, ownerId }] : [];
  });
  if (missingOwners.length > 0) {
    throw new ModuleSelectionError('Nested modules require their owning module to be selected.', { missingOwners });
    for (const adapter of options.adapters) {
      assertAdminCapabilityManifest(adapter.manifest);
      if (supplied.has(adapter.manifest.id)) throw new AdminError("conflict", `Duplicate admin module: ${adapter.manifest.id}.`);
      const declared = new Set(adapter.manifest.operations.map((operation) => operation.id));
      const registered = Object.keys(adapter.handlers);
      const missing = [...declared].filter((operationId) => typeof adapter.handlers[operationId] !== "function");
      const unknown = registered.filter((operationId) => !declared.has(operationId));
      if (missing.length || unknown.length) {
        throw new AdminError("invalid_argument", `Admin module ${adapter.manifest.id} must register exact handler coverage.`, {
          details: { moduleId: adapter.manifest.id, missing, unknown },
        });
      }
      supplied.set(adapter.manifest.id, adapter);
    }

    if (!Array.isArray(options.enabledModules)) {
      throw new AdminError("invalid_argument", "Admin registry requires an explicit enabledModules allowlist.");
    }
    const requested = [...new Set(options.enabledModules)];
    for (const moduleId of requested) {
      const adapter = supplied.get(moduleId);
      if (!adapter) throw new AdminError("dependency_unavailable", `Enabled admin module is not registered: ${moduleId}.`);
      if (adapter.manifest.availability === "unavailable") {
        throw new AdminError("dependency_unavailable", `Admin module ${moduleId} is not domain-backed and cannot be enabled.`, {
          details: { moduleId, reason: adapter.manifest.unavailableReason },
        });
      }
      if (adapter.manifest.availability === "folded") {
        throw new AdminError("dependency_unavailable", `Admin module ${moduleId} is folded into ${adapter.manifest.owner?.moduleId ?? "its owner"} and cannot be enabled independently.`, {
          details: { moduleId, ownerModuleId: adapter.manifest.owner?.moduleId },
        });
      }
    }
    const enabled = new Set(requested);
    for (const moduleId of requested) {
      const manifest = supplied.get(moduleId)!.manifest;
      for (const dependency of dependenciesOf(manifest)) {
        if (!enabled.has(dependency)) {
          throw new AdminError("dependency_unavailable", `Admin module ${moduleId} requires enabled module ${dependency}.`, {
            details: { moduleId, dependency },
          });
    });
  if (manifest.availability === "folded") {
    if (manifest.operations.length > 0)
      issues.push({ path: "$.operations", message: "must be empty for folded modules because the owner exposes their operations" });
    if (manifest.navigation && (Array.isArray(manifest.navigation) ? manifest.navigation.length > 0 : true))
      issues.push({ path: "$.navigation", message: "must be empty for folded modules" });
  }
  if (manifest.availability === "unavailable") {
    if (!manifest.unavailableReason?.trim())
      issues.push({ path: "$.unavailableReason", message: "is required for unavailable modules" });
    if (manifest.operations.length > 0)
      issues.push({ path: "$.operations", message: "must be empty for unavailable modules" });
    if (manifest.navigation && (Array.isArray(manifest.navigation) ? manifest.navigation.length > 0 : true))
      issues.push({ path: "$.navigation", message: "must be empty for unavailable modules" });
  } else if (manifest.unavailableReason !== undefined) {
    issues.push({ path: "$.unavailableReason", message: "is only valid for unavailable modules" });
  }
