import {
  MemoryAdminAuditSink,
  MemoryAdminIdempotencyStore,
  createAdminCapabilityAdapter,
  type AdminCapabilityManifest,
} from "@superfunctions/admin";
import { apiFnAdminCapability } from "@apifn/admin";
import { authFnAdminCapability } from "@authfn/admin";
import { billFnAdminCapability } from "@billfn/admin";
import { botFnAdminCapability } from "@botfn/admin";
import { cliFnAdminAdapter } from "@clifn/admin";
import { dataFnAdminCapability } from "@datafn/admin";
import { extFnAdminAdapter } from "@extfn/admin";
import { fileFnAdminCapability } from "@filefn/admin";
import { hostFnAdminCapability } from "@hostfn/admin";
import { plugFnAdminCapability } from "@plugfn/admin";
import { searchFnAdminCapability } from "@searchfn/admin";
import { describe, expect, it } from "vitest";
import {
  DEV_ENABLED_ADMIN_MODULE_IDS,
  DEV_REGISTERED_ADMIN_MODULE_IDS,
  createDevSuperConsoleInstallation,
  selectDevAdminAdapters,
  type DevAdminAdapters,
} from "../../examples/dev-installation.js";

function bind(manifest: AdminCapabilityManifest) {
  return createAdminCapabilityAdapter(
    manifest,
    Object.fromEntries(manifest.operations.map((operation) => [
      operation.id,
      async () => ({ ok: true, data: {} }),
    ])),
  );
}

function devAdapters(): DevAdminAdapters {
  return {
    apifn: bind(apiFnAdminCapability),
    authfn: bind(authFnAdminCapability),
    billfn: bind(billFnAdminCapability),
    botfn: bind(botFnAdminCapability),
    clifn: cliFnAdminAdapter,
    datafn: bind(dataFnAdminCapability),
    extfn: extFnAdminAdapter,
    filefn: bind(fileFnAdminCapability),
    hostfn: bind(hostFnAdminCapability),
    plugfn: bind(plugFnAdminCapability),
    searchfn: bind(searchFnAdminCapability),
  };
}

describe("representative dev installation", () => {
  it("registers every common dev adapter but enables only domain-backed modules", () => {
    const selection = selectDevAdminAdapters(devAdapters());
    expect(selection.adapters.map((adapter) => adapter.manifest.id)).toEqual(DEV_REGISTERED_ADMIN_MODULE_IDS);
    expect(selection.enabledModules).toEqual(DEV_ENABLED_ADMIN_MODULE_IDS);
    expect(selection.adapters.filter((adapter) => adapter.manifest.availability === "unavailable").map((adapter) => adapter.manifest.id)).toEqual(["clifn", "extfn"]);
  });

  it("creates an executable registry without enabling CliFn or ExtFn", () => {
    const console = createDevSuperConsoleInstallation({
      adapters: devAdapters(),
      auth: {
        authenticate: async () => null,
        authorizeScope: async () => null,
        authorizeMutation: async () => undefined,
      },
      shellPolicy: { authorize: () => true },
      audit: new MemoryAdminAuditSink(),
      idempotency: new MemoryAdminIdempotencyStore(),
      confirmation: {
        issue: async () => ({ token: "test", expiresAt: new Date(Date.now() + 60_000).toISOString() }),
        verify: async () => true,
      },
      openApiSecuritySchemes: {
        operatorSession: { type: "apiKey", in: "cookie", name: "session" },
        operatorApiKey: { type: "http", scheme: "bearer" },
      },
    });

    expect(console.registry.enabledModuleIds).toEqual(DEV_ENABLED_ADMIN_MODULE_IDS);
    expect(console.registry.enabledModuleIds).not.toContain("clifn");
    expect(console.registry.enabledModuleIds).not.toContain("extfn");
  });

  it("fails closed if an unavailable declaration is accidentally treated as enabled", () => {
    const adapters = { ...devAdapters(), clifn: bind(apiFnAdminCapability) } as DevAdminAdapters;
    expect(() => selectDevAdminAdapters(adapters)).toThrow(/registered as clifn exposes manifest apifn/);
  });
});

import type { AdminCapabilityAdapter } from "@superfunctions/admin";
import {
  createSuperConsole,
  type SuperConsole,
  type SuperConsoleOptions,
} from "../src/lib/server/index.js";

export const DEV_ENABLED_ADMIN_MODULE_IDS = [
  "apifn",
  "authfn",
  "billfn",
  "botfn",
  "datafn",
  "filefn",
  "hostfn",
  "plugfn",
  "searchfn",
] as const;

export const DEV_UNAVAILABLE_ADMIN_MODULE_IDS = ["clifn", "extfn"] as const;

export const DEV_REGISTERED_ADMIN_MODULE_IDS = [
  ...DEV_ENABLED_ADMIN_MODULE_IDS,
  ...DEV_UNAVAILABLE_ADMIN_MODULE_IDS,
] as const;

export type DevAdminModuleId = (typeof DEV_REGISTERED_ADMIN_MODULE_IDS)[number];

export type DevAdminAdapters = Readonly<Record<DevAdminModuleId, AdminCapabilityAdapter>>;

export interface DevAdminSelection {
  adapters: readonly AdminCapabilityAdapter[];
  enabledModules: readonly (typeof DEV_ENABLED_ADMIN_MODULE_IDS)[number][];
}

/**
 * The representative `dev` composition is an explicit allowlist. CliFn and
 * ExtFn remain registered so discovery can explain why they are unavailable,
 * but they are never enabled without a domain-backed operator service.
 */
export function selectDevAdminAdapters(adapters: DevAdminAdapters): DevAdminSelection {
  const registered = DEV_REGISTERED_ADMIN_MODULE_IDS.map((moduleId) => {
    const adapter = adapters[moduleId];
    if (adapter.manifest.id !== moduleId) {
      throw new Error(`The dev admin adapter registered as ${moduleId} exposes manifest ${adapter.manifest.id}.`);
    }
    return adapter;
  });

  for (const moduleId of DEV_ENABLED_ADMIN_MODULE_IDS) {
    if (adapters[moduleId].manifest.availability === "unavailable") {
      throw new Error(`The dev admin module ${moduleId} cannot be enabled without a domain-backed service.`);
    }
  }
  for (const moduleId of DEV_UNAVAILABLE_ADMIN_MODULE_IDS) {
    if (adapters[moduleId].manifest.availability !== "unavailable") {
      throw new Error(`The dev admin module ${moduleId} must remain explicitly unavailable until it has a safe operator service.`);
    }
  }

  return {
    adapters: registered,
    enabledModules: DEV_ENABLED_ADMIN_MODULE_IDS,
  };
}

export type DevSuperConsoleOptions = Omit<SuperConsoleOptions, "adapters" | "enabledModules"> & {
  adapters: DevAdminAdapters;
};

/** Compose this from real function-owned adapters and deployment-owned infrastructure. */
export function createDevSuperConsoleInstallation(options: DevSuperConsoleOptions): SuperConsole {
  const { adapters, ...infrastructure } = options;
  return createSuperConsole({
    ...infrastructure,
    ...selectDevAdminAdapters(adapters),
  });
}

