+import { createUIFnError } from '@uifn/core/errors';
+
+export interface SSRGuard {
+  isBrowser: () => boolean;
+  assertClient: (feature: string) => void;
+  runClient: <T>(feature: string, callback: () => T, fallback: T) => T;
