 57	export function findFunctionAgnosticIssues(source, file = 'source.ts') {
 58	  /** @type {Set<string>} */
 59	  const findings = new Set();
 60	  const extension = extname(file);
 61	  for (const region of sourceRegions(source, extension)) {
 62	    const ast = ts.createSourceFile(file, region.source, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS);
 63	    /** @param {import('typescript').Node} node */
 64	    const lineFor = (node) => ast.getLineAndCharacterOfPosition(node.getStart(ast)).line + 1 + region.lineOffset;
 65	    /** @param {import('typescript').Node} node */
 66	    const visit = (node) => {
 67	      const moduleSpecifier = (ts.isImportDeclaration(node) || ts.isExportDeclaration(node))
 68	        ? node.moduleSpecifier
 69	        : ts.isCallExpression(node) && node.expression.kind === ts.SyntaxKind.ImportKeyword
 70	          ? node.arguments[0]
 71	          : undefined;
 72	      if (moduleSpecifier && ts.isStringLiteralLike(moduleSpecifier)) {
 73	        const identifier = functionPackage(moduleSpecifier.text)?.toLowerCase();
 74	        if (identifier && !allowedImplementationDependencies.has(identifier)) {
 75	          findings.add(`${lineFor(moduleSpecifier)}: concrete function package import ${moduleSpecifier.text}`);
 76	        }
 77	      }
 78	      if (ts.isIdentifier(node)) {
 79	        if (forbiddenCatalogSymbols.has(node.text)) {
 80	          findings.add(`${lineFor(node)}: fixed catalog symbol ${node.text}`);
 81	        }
 82	        const identifier = embeddedFunctionPackage(node.text);
 83	        if (identifier && concreteFunctionPackages.has(identifier) && !allowedImplementationDependencies.has(identifier)) {
 84	          findings.add(`${lineFor(node)}: concrete function identifier ${node.text}`);
 85	        }
 86	      }
 87	      ts.forEachChild(node, visit);
 88	    };
 89	    visit(ast);
 90	  }
 91	  return [...findings];
 92	}
 93	
 94	if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
 95	  const findings = [];
