102	    console.error('Super Console core must remain function-agnostic:\n' + findings.map((finding) => `- ${finding}`).join('\n'));
103	    process.exitCode = 1;
104	  } else {
105	    console.log('Super Console function-agnostic source guard passed.');
106	  }
107	}

