 1	import { isAbsolute } from 'node:path';
 2	import { pathToFileURL } from 'node:url';
 3	import type { SuperConsole } from './super-console.js';
 4	
 5	const INSTALLATION = Symbol.for('superfunctions.superconsole.installation.v1');
 6	const LOADER = Symbol.for('superfunctions.superconsole.installation-loader.v1');
 7	
 8	type InstallationGlobal = typeof globalThis & { [INSTALLATION]?: SuperConsole; [LOADER]?: Promise<SuperConsole> };
 9	
10	/** Configure one process-local, explicitly composed self-hosted installation. */
11	export function configureSuperConsole(console: SuperConsole): SuperConsole {
12	  if ((globalThis as InstallationGlobal)[INSTALLATION]) {
13	    throw new Error('Super Console is already configured for this process. Refusing to replace the active installation.');
14	  }
15	  (globalThis as InstallationGlobal)[INSTALLATION] = console;
16	  return console;
17	}
18	
19	export function getSuperConsole(): SuperConsole | undefined {
20	  return (globalThis as InstallationGlobal)[INSTALLATION];
21	}
22	
23	export function requireSuperConsole(): SuperConsole {
24	  const console = getSuperConsole();
25	  if (!console) {
26	    throw new Error('Super Console is not configured. Call configureSuperConsole(createSuperConsole(...)) during server startup.');
27	  }
28	  return console;
29	}
30	
31	export function clearSuperConsoleForTesting(): void {
32	  delete (globalThis as InstallationGlobal)[INSTALLATION];
33	  delete (globalThis as InstallationGlobal)[LOADER];
34	}
35	
36	/** Resolve only local installation modules; package/http/data URLs are rejected. */
37	export function resolveSuperConsoleInstallationUrl(specifier: string): string {
38	  const normalized = specifier.trim();
39	  if (!normalized) throw new Error('SUPERCONSOLE_INSTALLATION must not be empty.');
40	  if (normalized.startsWith('file://')) {
41	    try {
42	      const url = new URL(normalized);
43	      if (url.protocol !== 'file:') throw new Error();
44	      return url.href;
45	    } catch {
46	      throw new Error('SUPERCONSOLE_INSTALLATION contains an invalid file URL.');
47	    }
48	  }
49	  if (!isAbsolute(normalized)) {
50	    throw new Error('SUPERCONSOLE_INSTALLATION must be an absolute filesystem path or file URL.');
51	  }
52	  return pathToFileURL(normalized).href;
53	}
54	
55	/**
56	 * Load an explicitly configured installation module once. The module must be an
57	 * absolute file URL/path permitted by the server deployment and export either
58	 * `superConsole`, `default`, or `createSuperConsoleInstallation`.
59	 */
60	export async function loadSuperConsoleInstallation(specifier: string): Promise<SuperConsole> {
61	  const globals = globalThis as InstallationGlobal;
62	  if (globals[INSTALLATION]) return globals[INSTALLATION];
63	  globals[LOADER] ??= (async () => {
64	    const importUrl = resolveSuperConsoleInstallationUrl(specifier);
65	    const module = await import(/* @vite-ignore */ importUrl) as {
66	      default?: SuperConsole;
67	      superConsole?: SuperConsole;
68	      createSuperConsoleInstallation?: () => SuperConsole | Promise<SuperConsole>;
69	    };
70	    const candidate = module.createSuperConsoleInstallation
71	      ? await module.createSuperConsoleInstallation()
72	      : module.superConsole ?? module.default;
73	    if (!candidate || typeof candidate.handle !== 'function') {
74	      throw new Error('The Super Console installation module did not export a composed SuperConsole instance.');
75	    }
76	    return configureSuperConsole(candidate);
77	  })();
78	  return globals[LOADER];
79	}

