55	/**
56	 * Load an explicitly configured installation module once. The module must be an
57	 * absolute file URL/path permitted by the server deployment and export either
58	 * `superConsole`, `default`, or `createSuperConsoleInstallation`.
59	 */
60	export async function loadSuperConsoleInstallation(specifier: string): Promise<SuperConsole> {
61	  const globals = globalThis as InstallationGlobal;
62	  if (globals[INSTALLATION]) return globals[INSTALLATION];
63	  globals[LOADER] ??= (async () => {
64	    const importUrl = resolveSuperConsoleInstallationUrl(specifier);
65	    const module = await import(/* @vite-ignore */ importUrl) as {
66	      default?: SuperConsole;
67	      superConsole?: SuperConsole;
68	      createSuperConsoleInstallation?: () => SuperConsole | Promise<SuperConsole>;
69	    };
70	    const candidate = module.createSuperConsoleInstallation
71	      ? await module.createSuperConsoleInstallation()
72	      : module.superConsole ?? module.default;
73	    if (!candidate || typeof candidate.handle !== 'function') {
74	      throw new Error('The Super Console installation module did not export a composed SuperConsole instance.');
75	    }
76	    return configureSuperConsole(candidate);
77	  })();
