 1	import { getSuperConsole, loadSuperConsoleInstallation } from './installation.js';
 2	
 3	export async function bootConfiguredSuperConsole(specifier?: string): Promise<void> {
 4	  if (getSuperConsole()) return;
 5	  if (!specifier?.trim()) return;
 6	  // Installation import and composition validation are startup-fatal by design.
 7	  await loadSuperConsoleInstallation(specifier);
 8	}
 9	
10	export async function handleConfiguredSuperConsole(request: Request): Promise<Response> {
11	  const console = getSuperConsole();
12	  if (!console) {
13	    return new Response(JSON.stringify({
14	      ok: false,
15	      error: {
16	        code: 'SUPERCONSOLE_NOT_CONFIGURED',
17	        message: 'Super Console has not been composed for this server process.',
18	        status: 503,
19	      },
20	    }), {
21	      status: 503,
22	      headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' },
23	    });
24	  }
25	  return console.handle(request);
26	}

