 20	const ADMIN_SCOPE_HIERARCHY = [
 21	  {
 22	    key: 'installationId',
 23	    aliases: ['installationId', 'installation', 'organizationId', 'organization'],
 24	  },
 25	  { key: 'workspaceId', aliases: ['workspaceId', 'workspace'] },
 26	  { key: 'projectId', aliases: ['projectId', 'project'] },
 27	  { key: 'environmentId', aliases: ['environmentId', 'environment'] },
 28	] as const;
 29	
 30	export type AdminScopeQueryKey = (typeof ADMIN_SCOPE_QUERY_KEYS)[number];
 31	
 32	export type AdminFetch = (
 33	  input: RequestInfo | URL,
 34	  init?: RequestInit
 35	) => Promise<Response>;
 36	
 37	const SAFE_HTTP_METHODS = new Set(['GET', 'HEAD', 'OPTIONS']);
 38	const CONSOLE_NAVIGATION_PATH = /^\/(?:$|api(?:\/|$)|audit(?:\/|$)|mcp(?:\/|$)|modules(?:\/|$)|search(?:\/|$)|settings(?:\/|$)|sign-in(?:\/|$))/;
 39	let operatorCsrfCookieName: string | undefined;
 40	let operatorCsrfHeaderName = 'x-operator-csrf';
 41	
 42	export function setOperatorCsrf(
 43	  cookieName: string | undefined,
 44	  headerName: string | undefined,
 45	): void {
 46	  operatorCsrfCookieName = cookieName?.trim() || undefined;
 47	  operatorCsrfHeaderName = headerName?.trim().toLowerCase() || 'x-operator-csrf';
 48	}
 49	
 50	function readableCookies(): string | undefined {
 51	  return typeof document === 'undefined' ? undefined : document.cookie;
 52	}
 53	
 54	/**
 55	 * Resolves the auth provider's readable double-submit token by the exact cookie name
 56	 * projected into the authenticated session. A single-cookie fallback supports
 57	 * sign-in bootstrap without inferring anything from HTTP-only session cookies.
 58	 */
 59	export function operatorCsrfToken(
 60	  cookieHeader = readableCookies(),
 61	  cookieName = operatorCsrfCookieName
 62	): string | undefined {
 63	  if (!cookieHeader) return undefined;
 64	  const candidates: Array<{ name: string; value: string }> = [];
 65	  for (const part of cookieHeader.split(';')) {
 66	    const [rawName, ...rawValue] = part.trim().split('=');
 67	    if (cookieName ? rawName !== cookieName : !rawName.endsWith('.csrf')) continue;
 68	    const encoded = rawValue.join('=');
 69	    try {
 70	      candidates.push({ name: rawName, value: decodeURIComponent(encoded) });
 71	    } catch {
 72	      candidates.push({ name: rawName, value: encoded });
 73	    }
 74	  }
 75	  if (cookieName) return candidates[0]?.value;
 76	  return candidates.length === 1 ? candidates[0]?.value : undefined;
 77	}
