 79	/** Same-origin console transport with provider-defined CSRF propagation for mutations. */
 80	export async function fetchConsole(
 81	  input: RequestInfo | URL,
 82	  init: RequestInit = {},
 83	  fetcher: AdminFetch = globalThis.fetch
 84	): Promise<Response> {
 85	  const headers = new Headers(init.headers);
 86	  const method = (init.method ?? 'GET').toUpperCase();
 87	  if (!SAFE_HTTP_METHODS.has(method) && !headers.has(operatorCsrfHeaderName)) {
 88	    const token = operatorCsrfToken();
 89	    if (token) headers.set(operatorCsrfHeaderName, token);
 90	  }
 91	  return fetcher(input, {
 92	    ...init,
 93	    method,
 94	    headers,
 95	    credentials: 'same-origin',
 96	  });
 97	}
