100	  | {
101	      ok: true;
102	      data: T;
103	      requestId?: string;
104	      correlationId?: string;
105	      auditId?: string;
106	      page?: { nextCursor?: string | null; hasMore?: boolean };
107	      warnings?: readonly string[];
108	      meta?: Readonly<Record<string, unknown>>;
109	    }
110	  | { ok: false; error: AdminErrorViewModel };
111	
112	export function withAdminScope(path: string, scope?: URLSearchParams): string {
113	  if (!scope) return path;
114	  const url = new URL(path, 'http://superconsole.local');
115	  const explicitBoundary = ADMIN_SCOPE_HIERARCHY.findIndex(({ aliases }) =>
116	    aliases.some((alias) => url.searchParams.has(alias))
117	  );
118	  for (const [index, { key, aliases }] of ADMIN_SCOPE_HIERARCHY.entries()) {
119	    if (aliases.some((alias) => url.searchParams.has(alias))) continue;
120	    if (explicitBoundary >= 0 && index > explicitBoundary) continue;
121	    const value = aliases.map((alias) => scope.get(alias)).find(Boolean);
122	    if (value) url.searchParams.set(key, value);
123	  }
124	  if (explicitBoundary < 0) {
125	    for (const key of ['namespace', 'region'] as const) {
126	      if (url.searchParams.has(key)) continue;
127	      const value = scope.get(key);
128	      if (value) url.searchParams.set(key, value);
129	    }
130	  }
131	  return `${url.pathname}${url.search}${url.hash}`;
132	}
133	
134	export function scopedConsoleHref(path: string, current: URLSearchParams): string {
135	  return withAdminScope(path, current);
136	}
