 41	function page<T>(values: readonly T[], input: PlugFnPageInput, context: AdminOperationContext): { items: T[]; nextCursor: string | null } {
 42	  const limit = normalizeAdminPageLimit(input.limit, { defaultLimit: 50, maxLimit: 100 });
 43	  const decoded = input.cursor ? decodeAdminCursor<{ offset?: unknown }>(input.cursor, context.scope) : { offset: 0 };
 44	  const offset = decoded.offset ?? 0;
 45	  if (!Number.isInteger(offset) || (offset as number) < 0) throw new AdminError("invalid_argument", "The PlugFn cursor is invalid.");
 46	  const items = values.slice(offset as number, (offset as number) + limit);
 47	  const nextOffset = (offset as number) + items.length;
 48	  return { items: [...items], nextCursor: nextOffset < values.length ? encodeAdminCursor(context.scope, { offset: nextOffset }) : null };
 49	}
