   139	  href: string,
   140	  level: 'organization' | 'workspace' | 'project' | 'environment',
   141	  value: string
   142	): string {
   143	  const url = new URL(href, 'http://superconsole.local');
   144	  const hierarchy = ['organization', 'workspace', 'project', 'environment'] as const;
   145	  if (level === 'organization') {
   146	    for (const alias of ADMIN_SCOPE_HIERARCHY[0].aliases) url.searchParams.delete(alias);
   147	    url.searchParams.set('installationId', value);
   148	  } else {
   149	    url.searchParams.set(`${level}Id`, value);
   150	    url.searchParams.delete(level);
   151	  }
   152	  for (const dependent of hierarchy.slice(hierarchy.indexOf(level) + 1)) {
   153	    url.searchParams.delete(`${dependent}Id`);
   154	    url.searchParams.delete(dependent);
   155	  }
   156	  url.searchParams.delete('namespace');
   157	  url.searchParams.delete('region');
   158	  return `${url.pathname}${url.search}${url.hash}`;
   159	}
