  1	import type { SearchAdapter, SearchDocument } from "@searchfn/adapter-contracts";
  2	import {
  3	  AdminError,
  4	  type AdminOperationContext,
  5	  type AdminOperationResult,
  6	} from "@superfunctions/admin";
  7	import type {
  8	  SearchFnAdminRecord,
  9	  SearchFnAdminService,
 10	  SearchFnItemOutput,
 11	  SearchFnListOutput,
 12	  SearchFnMutationOutput,
 13	} from "./types.js";
 14	
 15	type JsonRecord = Record<string, unknown>;
 16	
 17	export interface SearchFnDomainAdminServiceOptions {
 18	  /** Must resolve an adapter already isolated to the active scope and optional namespace/region. */
 19	  adapter(context: AdminOperationContext): SearchAdapter | Promise<SearchAdapter>;
 20	  /** Returns the configured index names visible inside the same isolated adapter. */
 21	  resources(context: AdminOperationContext): readonly string[] | Promise<readonly string[]>;
 22	}
 23	
 24	function object(value: unknown, name: string): JsonRecord {
 25	  if (!value || typeof value !== "object" || Array.isArray(value)) {
 26	    throw new AdminError("invalid_argument", `${name} must be an object.`);
 27	  }
 28	  return value as JsonRecord;
 29	}
 30	
 31	function string(value: unknown, name: string): string {
 32	  if (typeof value !== "string" || value.length === 0) {
 33	    throw new AdminError("invalid_argument", `${name} must be a non-empty string.`);
 34	  }
 35	  return value;
 36	}
 37	
 38	function item(value: object): AdminOperationResult<SearchFnItemOutput> {
 39	  return { ok: true, data: { item: { ...value } } };
 40	}
 41	
 42	function list(values: object[]): AdminOperationResult<SearchFnListOutput> {
 43	  return { ok: true, data: { items: values.map((value) => ({ ...value })), nextCursor: null } };
 44	}
 45	
 46	function accepted(value: JsonRecord): AdminOperationResult<SearchFnMutationOutput> {
 47	  return { ok: true, data: { accepted: true, ...value } };
 48	}
 49	
 50	function splitDocumentId(value: string): { resource: string; id: string | number } {
 51	  const separator = value.indexOf(":");
 52	  if (separator <= 0 || separator === value.length - 1) {
 53	    throw new AdminError("invalid_argument", "SearchFn document targets use the form resource:id.");
 54	  }
 55	  const id = value.slice(separator + 1);
 56	  return { resource: value.slice(0, separator), id: /^\d+$/.test(id) ? Number(id) : id };
 57	}
 58	
 59	function documents(value: unknown): SearchDocument[] {
 60	  if (!Array.isArray(value) || value.length === 0) {
 61	    throw new AdminError("invalid_argument", "payload.documents must be a non-empty array.");
 62	  }
 63	  return value.map((entry, index) => {
 64	    const document = object(entry, `payload.documents[${index}]`);
 65	    const id = document.id;
 66	    if (typeof id !== "string" && typeof id !== "number") {
 67	      throw new AdminError("invalid_argument", `payload.documents[${index}].id must be a string or number.`);
 68	    }
 69	    const fields = object(document.fields, `payload.documents[${index}].fields`);
 70	    if (Object.values(fields).some((field) => typeof field !== "string")) {
 71	      throw new AdminError("invalid_argument", `payload.documents[${index}].fields values must be strings.`);
 72	    }
 73	    return { id, fields: fields as Record<string, string> };
 74	  });
 75	}
 76	
 77	/** Delegates to the configured SearchAdapter; no raw backend or cross-scope query is constructed here. */
 78	export function createSearchFnDomainAdminService(
 79	  options: SearchFnDomainAdminServiceOptions,
 80	): SearchFnAdminService {
 81	  const state = async (context: AdminOperationContext) => {
 82	    const adapter = await options.adapter(context);
 83	    const resources = [...await options.resources(context)];
 84	    return {
 85	      adapter,
 86	      resources,
 87	      adapterInfo: {
 88	        id: adapter.name,
 89	        name: adapter.name,
 90	        status: "available",
 91	        capabilities: adapter.capabilities ?? {},
 92	      } satisfies SearchFnAdminRecord,
 93	      indexInfo: resources.map((resource) => ({ id: resource, name: resource, status: "available" })),
 94	    };
 95	  };
 96	
 97	  return {
 98	    async listAdapters(_input, context) {
 99	      const { adapterInfo } = await state(context);
100	      return list([adapterInfo]);
101	    },
102	    async getAdapter(input, context) {
103	      const { adapter, adapterInfo } = await state(context);
104	      if (string(input.id, "id") !== adapter.name) {
105	        throw new AdminError("not_found", "SearchFn adapter was not found in the active scope.");
106	      }
107	      return item(adapterInfo);
108	    },
109	    async listIndexes(_input, context) {
110	      return list((await state(context)).indexInfo);
111	    },
112	    async getIndex(input, context) {
113	      const { indexInfo } = await state(context);
114	      const found = indexInfo.find((entry) => entry.id === string(input.id, "id"));
115	      if (!found) throw new AdminError("not_found", "SearchFn index was not found in the active scope.");
116	      return item(found);
117	    },
118	    async listHealth(_input, context) {
119	      const { adapter } = await state(context);
120	      return list([{ id: adapter.name, adapter: adapter.name, state: "ok", capabilities: adapter.capabilities ?? {} }]);
121	    },
122	    async getHealth(input, context) {
123	      const { adapter } = await state(context);
124	      if (string(input.id, "id") !== adapter.name) {
125	        throw new AdminError("not_found", "SearchFn health target was not found.");
126	      }
127	      return item({ id: adapter.name, adapter: adapter.name, state: "ok", capabilities: adapter.capabilities ?? {} });
128	    },
129	    async indexDocument(input, context) {
130	      const { adapter, resources } = await state(context);
131	      const inputValue = object(input, "input");
132	      const target = splitDocumentId(string(inputValue.id, "id"));
133	      if (!resources.includes(target.resource)) throw new AdminError("not_found", "SearchFn index was not found in the active scope.");
134	      const fields = object(object(inputValue.payload, "payload").fields, "payload.fields");
135	      if (Object.values(fields).some((field) => typeof field !== "string")) {
136	        throw new AdminError("invalid_argument", "payload.fields values must be strings.");
137	      }
138	      await adapter.index({
139	        resource: target.resource,
140	        documents: [{ id: target.id, fields: fields as Record<string, string> }],
141	        signal: context.signal,
142	      });
143	      return accepted({ indexed: 1, resource: target.resource });
144	    },
145	    async batchIndex(input, context) {
146	      const { adapter, resources } = await state(context);
147	      const payload = object(object(input, "input").payload, "payload");
148	      const resource = string(payload.resource, "payload.resource");
149	      if (!resources.includes(resource)) throw new AdminError("not_found", "SearchFn index was not found in the active scope.");
150	      const entries = documents(payload.documents);

