import type { PlugFnConnectionOperation, PlugFnPrincipal } from '../types/config.js';
import type { Connection } from '../types/connection.js';

export function tenantMatches(
  connectionTenantId: string | undefined,
  actorTenantId: string | undefined
): boolean {
  return connectionTenantId === actorTenantId;
}

export function hasAny(values: unknown, candidates: readonly string[]): boolean {
  if (!Array.isArray(values) || values.length === 0) {
    return false;
  }

  const valueSet = new Set(values.filter((value): value is string => typeof value === 'string'));
  return candidates.some((candidate) => valueSet.has(candidate));
}

export function connectionMatchesActor(
  connection: Connection,
  actor: PlugFnPrincipal,
  operation?: PlugFnConnectionOperation
): boolean {
  if (!tenantMatches(connection.tenantId, actor.tenantId)) {
    return false;
  }

  if (
    ((connection.ownerKind === undefined || connection.ownerKind === 'user') &&
      connection.userId === actor.userId) ||
    (connection.ownerKind === 'user' && connection.ownerId === actor.userId)
  ) {
    return true;
  }

  if (connection.ownerKind === 'organization') {
    return (
      connection.installedByUserId === actor.userId ||
      (Boolean(connection.organizationId) &&
        Boolean(actor.organizationId) &&
        connection.organizationId === actor.organizationId &&
        hasAny(actor.roles, ['admin', 'owner', 'org:admin']))
    );
  }

  if (connection.ownerKind !== 'delegated') {
    return false;
  }

  if (connection.installedByUserId === actor.userId) {
    return true;
  }

  const allowedGrants = connection.grants ?? [];
  const operationGrants =
    operation === 'disconnect' ? ['disconnect', 'revoke'] : operation ? [operation] : allowedGrants;
  const operationAllowed = hasAny(allowedGrants, operationGrants);

  if (connection.delegatedToUserId === actor.userId) {
    return operationAllowed;
  }

  return (
    operationAllowed &&
    Boolean(connection.organizationId) &&
    Boolean(actor.organizationId) &&
    connection.organizationId === actor.organizationId &&
    hasAny(actor.grants, operationGrants)
  );
}
export type PlugFnOwnerKind = 'user' | 'organization' | 'delegated';

export type PlugFnConnectionOwner =
  | { kind: 'user'; userId: string; tenantId?: string }
  | { kind: 'organization'; organizationId: string; installedByUserId: string; tenantId?: string }
  | {
      kind: 'delegated';
      organizationId: string;
      delegatedToUserId: string;
      installedByUserId: string;
      grants: string[];
      tenantId?: string;
    };

export interface PlugFnActor {
  userId: string;
  tenantId?: string;
  organizationId?: string;
  roles?: string[];
  grants?: string[];
}

export interface PlugFnProviderRuntimeContext {
  provider: string;
  tenantId?: string;
  owner?: PlugFnConnectionOwner;
  actor?: PlugFnActor;
}

export interface PlugFnOAuthClientConfig {
  clientId: string;
  clientSecret: string;
  redirectUris?: string[];
  scopes?: string[];
}

export interface PlugFnSecretResolverConfig {
  resolveOAuthClient(
    context: PlugFnProviderRuntimeContext
  ): Promise<PlugFnOAuthClientConfig | null> | PlugFnOAuthClientConfig | null;
}

export interface PlugFnProviderInstallation {
  id: string;
  provider: string;
  ownerKind: PlugFnOwnerKind;
  ownerId: string;
  tenantId?: string;
  organizationId?: string;
  installedByUserId?: string;
  delegatedToUserId?: string;
  status: 'active' | 'disabled' | 'revoked' | 'error';
  scopes?: string[];
  metadata?: Record<string, unknown>;
  createdAt: Date;
  updatedAt: Date;
}

export interface PlugFnConnectionGrant {
  id: string;
  connectionId: string;
  granteeUserId: string;
  grant: string;
  createdAt: Date;
  expiresAt?: Date;
}

export interface PlugFnWebhookReceipt {
  id: string;
  provider: string;
