    return false;
  }
  return expiresAtMs <= Date.now();
}

function tryParseCursor(cursor: string): CursorTuple | null {
  try {
    const decoded = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8')) as Partial<CursorTuple>;
