 3	export function compareCodeUnits(left: string, right: string): number {
 4	  return left < right ? -1 : left > right ? 1 : 0;
 5	}
 6	
 7	export function canonicalize(value: unknown): unknown {
 8	  if (Array.isArray(value)) {
 9	    return value.map(canonicalize);
10	  }
11	  if (value && typeof value === "object") {
12	    return Object.fromEntries(
13	      Object.entries(value as Record<string, unknown>)
14	        .filter(([, entry]) => entry !== undefined)
15	        .sort(([left], [right]) => compareCodeUnits(left, right))
16	        .map(([key, entry]) => [key, canonicalize(entry)]),
17	    );
18	  }
19	  return value;
20	}
21	
22	export function canonicalJson(value: unknown): string {
23	  return JSON.stringify(canonicalize(value));
24	}
25	
26	export function sha256(value: unknown): string {
27	  return createHash("sha256").update(canonicalJson(value)).digest("hex");
28	}

