 1	import { access, readdir } from "node:fs/promises";
 2	import { dirname, join, resolve } from "node:path";
 3	import { fileURLToPath, pathToFileURL } from "node:url";
 4	
 5	const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), "../../..");
 6	const results = [];
 7	const transport = {
 8	  registry: async () => [],
 9	  invokeOperation: async () => ({ ok: true, data: {} }),
10	  invokeOperationRaw: async () => ({ response: new Response(), payload: { ok: true, data: {} } }),
11	};
12	for (const name of (await readdir(repositoryRoot)).filter((entry) => entry.endsWith("fn")).sort()) {
13	  const entry = join(repositoryRoot, name, "admin", "dist", "index.js");
14	  try { await access(entry); } catch { continue; }
15	  const exports = await import(pathToFileURL(entry).href);
16	  const manifest = exports.adminCapability
17	    ?? Object.values(exports).find((value) => value?.schemaVersion === "1.0" && value?.id === name);
18	  if (!manifest || ["folded", "unavailable"].includes(manifest.availability)) continue;
19	  const factories = Object.entries(exports).filter(([key, value]) => /^create[A-Za-z0-9]+AdminClient$/.test(key) && typeof value === "function");
20	  if (factories.length !== 1) {
21	    results.push({ moduleId: name, status: "fail", reason: `Expected one named admin client factory, found ${factories.length}.` });
22	    continue;
23	  }
24	  const [factoryName, factory] = factories[0];
25	  const client = factory(transport);
26	  const missing = ["operations", "availability", "invoke", "raw", "pages"].filter((key) => key === "operations" ? !client[key] : typeof client[key] !== "function");
27	  results.push({
28	    moduleId: name,
29	    factory: factoryName,
30	    operationCount: Object.keys(client.operations ?? {}).length,
31	    status: missing.length === 0 && Object.keys(client.operations).length === manifest.operations.length ? "pass" : "fail",
32	    ...(missing.length ? { missing } : {}),
33	  });
34	}
35	const report = {
36	  schemaVersion: "1.0",
37	  summary: { reviewed: results.length, passed: results.filter((result) => result.status === "pass").length, failed: results.filter((result) => result.status === "fail").length },
38	  results,
39	};
40	process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
41	if (report.summary.failed > 0) process.exitCode = 1;

