 1	import { ADMIN_API_PREFIX, fetchAdmin, safeConsoleNavigationHref, withAdminScope } from '$lib/components/admin-api';
 2	import type { PageLoad } from './$types';
 3	
 4	interface SearchResultViewModel {
 5	  id: string;
 6	  title: string;
 7	  description?: string;
 8	  moduleId: string;
 9	  resource?: string;
10	  href: string;
11	  status?: string;
12	  updatedAt?: string;
13	}
14	
15	export const load: PageLoad = async ({ fetch, url, depends }) => {
16	  const query = url.searchParams.get('q')?.trim() ?? '';
17	  depends(`superconsole:search:${query}`);
18	  if (!query) return { query, results: [], total: 0 };
19	  const result = await fetchAdmin<{ results: SearchResultViewModel[]; total?: number }>(
20	    fetch,
21	    withAdminScope(`${ADMIN_API_PREFIX}/search?q=${encodeURIComponent(query)}`, url.searchParams)
22	  );
23	  return {
24	    query,
25	    results: result.ok ? (result.data.results ?? []).flatMap((item) => {
26	      const href = safeConsoleNavigationHref(item.href, url.origin);
27	      return href ? [{ ...item, href }] : [];
28	    }) : [],
29	    total: result.ok ? result.data.total ?? result.data.results?.length ?? 0 : 0,
30	    loadError: result.ok ? undefined : result.error,
31	  };
32	};

