 1	<script lang="ts">
 2	  import { goto } from '$app/navigation';
 3	  import { page } from '$app/state';
 4	  import { ButtonIcon, ButtonLabel, ButtonRoot } from '@uifn/components-svelte/button';
 5	  import { CardAction, CardContent, CardDescription, CardHeader, CardRoot, CardTitle } from '@uifn/components-svelte/card';
 6	  import { InputRoot } from '@uifn/components-svelte/input';
 7	  import ConsoleIcon from '$lib/components/ConsoleIcon.svelte';
 8	  import PageHeader from '$lib/components/PageHeader.svelte';
 9	  import StatePanel from '$lib/components/StatePanel.svelte';
10	  import StatusBadge from '$lib/components/StatusBadge.svelte';
11	  import { safeConsoleNavigationHref, scopedConsoleHref } from '$lib/components/admin-api';
12	  import { formatValue } from '$lib/components/view-models';
13	  import type { PageData } from './$types';
14	
15	  let { data }: { data: PageData } = $props();
16	  let query = $state('');
17	  $effect(() => { query = data.query; });
18	
19	  function submit() {
20	    const trimmed = query.trim();
21	    void goto(scopedConsoleHref(trimmed ? `/search?q=${encodeURIComponent(trimmed)}` : '/search', page.url.searchParams));
22	  }
23	
24	  function openResult(href: string) {
25	    const safeHref = safeConsoleNavigationHref(href, page.url.origin);
26	    if (safeHref) void goto(scopedConsoleHref(safeHref, page.url.searchParams));
27	  }
28	</script>
29	
30	<PageHeader eyebrow="Operator search" title="Global search" description="Find resources across only the modules enabled in the active operator scope." />
31	
32	<form class="global-search" onsubmit={(event) => { event.preventDefault(); submit(); }}>
33	  <ConsoleIcon name="search" size={22} />
34	  <InputRoot value={query} oninput={(event: Event) => (query = (event.currentTarget as HTMLInputElement).value)} name="q" placeholder="Search users, runs, messages, deployments, files…" aria-label="Search all enabled modules" autofocus />
35	  <ButtonRoot type="submit"><ButtonLabel>Search</ButtonLabel></ButtonRoot>
36	</form>
37	
38	{#if data.loadError?.status === 403}
39	  <StatePanel kind="forbidden" error={data.loadError} />
40	{:else if data.loadError}
41	  <StatePanel kind="error" error={data.loadError} />
42	{:else if !data.query}
43	  <StatePanel kind="empty" title="Search the active scope" message="Results are permission filtered and grouped by their owning Superfunction." />
44	{:else if data.results.length === 0}
45	  <StatePanel kind="empty" title={`No results for “${data.query}”`} message="Try a resource ID, operator-visible name, email, status, or module-specific term." />
46	{:else}
47	  <div class="search-results-heading"><strong>{data.total} results</strong><span>for “{data.query}”</span></div>
48	  <div class="search-results">
49	    {#each data.results as result (`${result.moduleId}-${result.id}`)}
50	      <CardRoot class="search-result">
51	        <CardHeader><StatusBadge label={result.moduleId} tone="info" /><CardTitle>{result.title}</CardTitle><CardDescription>{result.description ?? result.resource ?? 'Administration resource'}</CardDescription><CardAction>{#if result.status}<StatusBadge status={result.status} />{/if}</CardAction></CardHeader>
52	        <CardContent>{#if result.updatedAt}<span>Updated {formatValue(result.updatedAt, 'datetime')}</span>{/if}<ButtonRoot variant="ghost" size="sm" onclick={() => openResult(result.href)}><ButtonLabel>Open result</ButtonLabel><ButtonIcon><ConsoleIcon name="arrow-right" /></ButtonIcon></ButtonRoot></CardContent>
53	      </CardRoot>
54	    {/each}
55	  </div>
56	{/if}

