 3	export interface SSRGuard {
 4	  isBrowser: () => boolean;
 5	  assertClient: (feature: string) => void;
 6	  runClient: <T>(feature: string, callback: () => T, fallback: T) => T;
 7	}
 8	
 9	export function createSSRGuard(options: { canUseDOM?: () => boolean } = {}): SSRGuard {
10	  const canUseDOM =
11	    options.canUseDOM ??
12	    (() => typeof globalThis !== 'undefined' && 'document' in globalThis);
13	
14	  return {
15	    isBrowser() {
16	      return canUseDOM();
17	    },
18	    assertClient(feature) {
19	      if (canUseDOM()) {
20	        return;
21	      }
22	
23	      throw createUIFnError({
24	        code: 'UIFN_ERR_UNSUPPORTED_ENVIRONMENT',
25	        package: '@uifn/adapter-kit',
26	        component: 'SSRGuard',
27	        message: 'Adapter feature requires a client environment.',
28	        details: {
29	          feature,
30	        },
31	      });
32	    },
33	    runClient(feature, callback, fallback) {
34	      if (!canUseDOM()) {
35	        return fallback;
36	      }
37	
38	      this.assertClient(feature);
39	      return callback();
40	    },
41	  };
42	}

