 1	export interface AsyncListState<T> {
 2	  readonly status: 'idle' | 'loading' | 'loaded' | 'error';
 3	  readonly items: readonly T[];
 4	  readonly error: unknown;
 5	  readonly requestId: number;
 6	}
 7	
 8	export interface AsyncListLoadContext {
 9	  readonly signal: AbortSignal;
10	  readonly filterText: string;
11	}
12	
13	export interface AsyncList<T> {
14	  readonly state: AsyncListState<T>;
15	  load(filterText?: string): Promise<AsyncListState<T>>;
16	  cancel(): void;
17	  subscribe(callback: (state: AsyncListState<T>) => void): () => void;
18	  destroy(): void;
19	}
20	
21	export function createAsyncList<T>(options: {
22	  readonly load: (context: AsyncListLoadContext) => Promise<readonly T[]>;
23	  readonly initialItems?: readonly T[];
24	}): AsyncList<T> {
25	  let state: AsyncListState<T> = Object.freeze({ status: 'idle', items: Object.freeze([...(options.initialItems ?? [])]), error: null, requestId: 0 });
26	  let controller: AbortController | null = null;
27	  let destroyed = false;
28	  const listeners = new Set<(state: AsyncListState<T>) => void>();
29	  const publish = (next: AsyncListState<T>) => {
30	    state = Object.freeze(next);
31	    listeners.forEach((listener) => listener(state));
32	  };
33	  const api: AsyncList<T> = {
34	    get state() { return state; },
35	    async load(filterText = '') {
36	      if (destroyed) return state;
37	      controller?.abort();
38	      controller = new AbortController();
39	      const requestId = state.requestId + 1;
40	      const active = controller;
41	      publish({ ...state, status: 'loading', error: null, requestId });
42	      try {
43	        const items = await options.load({ signal: active.signal, filterText });
44	        if (!destroyed && !active.signal.aborted && requestId === state.requestId) {
45	          publish({ status: 'loaded', items: Object.freeze([...items]), error: null, requestId });
46	        }
47	      } catch (error) {
48	        if (!destroyed && !active.signal.aborted && requestId === state.requestId) {
49	          publish({ ...state, status: 'error', error, requestId });
50	        }
51	      }
52	      return state;
53	    },
54	    cancel() { controller?.abort(); },
55	    subscribe(callback) {
56	      if (destroyed) return () => undefined;
57	      listeners.add(callback);
58	      callback(state);
59	      return () => listeners.delete(callback);
60	    },
61	    destroy() {
62	      if (destroyed) return;
63	      destroyed = true;
64	      controller?.abort();
65	      listeners.clear();
66	    },
67	  };
68	  return api;
69	}

