     1	import type { AdminCapabilityManifest, AdminOperationDefinition } from "./types.js";
     2	
     3	export type AdminMutationRiskCategory = "credential-lifecycle" | "external-side-effect";
     4	
     5	export interface AdminMutationRiskReview {
     6	  moduleId: string;
     7	  operationId: string;
     8	  categories: readonly AdminMutationRiskCategory[];
     9	  classification: AdminOperationDefinition["safety"]["classification"];
    10	  confirmationMethod?: NonNullable<AdminOperationDefinition["safety"]["confirmation"]>["method"];
    11	  status: "pass" | "fail";
    12	  reason: string;
    13	}
    14	
    15	const CREDENTIAL_RESOURCE = /(?:^|\.)(?:credentials?|secrets?|secret-sets?|secret-set-members?|device-tokens?|auth-sessions?|connections?|provider-installations?|variables?|grants?|share-links?)(?:\.|$)/;
    16	const EXTERNAL_ACTION = /(?:^|\.)(?:send-[a-z0-9-]+|publish|unpublish|deploy|rollback|attach|detach|refund-payment|change-subscription|cancel-subscription|reconcile-provider|manage-domain|create-webhook|expire-inbox|purge|enable|disable|run|enqueue|retry-run|cancel-run)$/;
    17	
    18	/**
    19	 * Produces deterministic JSON-safe evidence for every mutation whose operation
    20	 * identity declares credential lifecycle or an externally visible side effect.
    21	 * Credential lifecycle requires recent-auth, MFA, or approval. External side
    22	 * effects require explicit confirmation metadata at minimum.
    23	 */
    24	export function reviewAdminMutationRisks(
    25	  manifests: readonly AdminCapabilityManifest[],
    26	): AdminMutationRiskReview[] {
    27	  const reviews: AdminMutationRiskReview[] = [];
    28	  for (const manifest of [...manifests].sort((left, right) => left.id.localeCompare(right.id))) {
    29	    for (const operation of [...manifest.operations].sort((left, right) => left.id.localeCompare(right.id))) {
    30	      if (operation.safety.classification === "read") continue;
    31	      const categories: AdminMutationRiskCategory[] = [];
    32	      // Read operations were removed above, so every write under a
    33	      // credential-bearing resource is reviewed even when its action name is
    34	      // domain-specific (for example rotate-credential or create-share).
    35	      if (CREDENTIAL_RESOURCE.test(operation.id)) categories.push("credential-lifecycle");
    36	      if (EXTERNAL_ACTION.test(operation.id)) categories.push("external-side-effect");
    37	      if (categories.length === 0) continue;
    38	      const confirmation = operation.safety.confirmation;
    39	      const credentialStrong = !categories.includes("credential-lifecycle") || Boolean(confirmation && ["recent-auth", "mfa", "approval"].includes(confirmation.method));
    40	      const externalConfirmed = !categories.includes("external-side-effect") || Boolean(confirmation);
    41	      const status = operation.safety.requiresConfirmation && credentialStrong && externalConfirmed ? "pass" : "fail";
    42	      reviews.push({
    43	        moduleId: manifest.id,
    44	        operationId: operation.id,
    45	        categories,
    46	        classification: operation.safety.classification,
    47	        ...(confirmation ? { confirmationMethod: confirmation.method } : {}),
    48	        status,
    49	        reason: status === "pass"
    50	          ? "Declared confirmation meets the identified mutation risk."
    51	          : categories.includes("credential-lifecycle") && !credentialStrong
    52	            ? "Credential lifecycle requires recent-auth, MFA, or approval confirmation metadata."
    53	            : "External side effects require explicit confirmation metadata.",
    54	      });
    55	    }
    56	  }
    57	  return reviews;
    58	}


