     1	export type AdapterCleanup = () => void;
     2	
     3	export interface LifecycleScope {
     4	  add: (cleanup: AdapterCleanup) => AdapterCleanup;
     5	  run: <T>(createCleanup: () => T | AdapterCleanup) => T | AdapterCleanup;
     6	  cleanup: () => void;
     7	  active: () => boolean;
     8	  size: () => number;
     9	}
    10	
    11	export function createLifecycleScope(): LifecycleScope {
    12	  const cleanups = new Set<AdapterCleanup>();
    13	  let isActive = true;
    14	
    15	  const remove = (cleanup: AdapterCleanup) => {
    16	    cleanups.delete(cleanup);
    17	  };
    18	
    19	  return {
    20	    add(cleanup) {
    21	      if (!isActive) {
    22	        cleanup();
    23	        return () => undefined;
    24	      }
    25	
    26	      cleanups.add(cleanup);
    27	      return () => remove(cleanup);
    28	    },
    29	    run(createCleanup) {
    30	      const cleanup = createCleanup();
    31	
    32	      if (typeof cleanup === 'function') {
    33	        this.add(cleanup as AdapterCleanup);
    34	      }
    35	
    36	      return cleanup;
    37	    },
    38	    cleanup() {
    39	      if (!isActive) {
    40	        return;
    41	      }
    42	
    43	      isActive = false;
    44	      Array.from(cleanups)
    45	        .reverse()
    46	        .forEach((cleanup) => cleanup());
    47	      cleanups.clear();
    48	    },
    49	    active() {
    50	      return isActive;
    51	    },
    52	    size() {
    53	      return cleanups.size;
    54	    },
    55	  };
    56	}


