const cmds=[
"npx turbo run build --filter=@filefn/docs --force",
"npx turbo run build --filter=@authfn/docs --force"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:wd,yield_time_ms:30000,max_output_tokens:18000})));
for(let i=0;i<cmds.length;i++){text(`\n===== ${cmds[i]} (exit ${rs[i].exit_code}) =====\n${rs[i].output}`);if(rs[i].session_id)text(JSON.stringify({cmd:cmds[i],session_id:rs[i].session_id}));}

