    /** @param {import('typescript').Node} node */
    const visit = (node) => {
      const moduleSpecifier = (ts.isImportDeclaration(node) || ts.isExportDeclaration(node))
        ? node.moduleSpecifier
        : ts.isCallExpression(node) && node.expression.kind === ts.SyntaxKind.ImportKeyword
          ? node.arguments[0]
          : undefined;
      if (moduleSpecifier && ts.isStringLiteralLike(moduleSpecifier)) {
        const identifier = functionPackage(moduleSpecifier.text)?.toLowerCase();
        if (identifier && !allowedImplementationDependencies.has(identifier)) {
          findings.add(`${lineFor(moduleSpecifier)}: concrete function package import ${moduleSpecifier.text}`);
        }
      }
      if (ts.isIdentifier(node)) {
        if (forbiddenCatalogSymbols.has(node.text)) {
          findings.add(`${lineFor(node)}: fixed catalog symbol ${node.text}`);
        }
        const identifier = embeddedFunctionPackage(node.text);
        if (identifier && concreteFunctionPackages.has(identifier) && !allowedImplementationDependencies.has(identifier)) {
          findings.add(`${lineFor(node)}: concrete function identifier ${node.text}`);
        }
      }
      ts.forEachChild(node, visit);
    };
    visit(ast);
  }
  return [...findings];
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const findings = [];
  for (const file of files(sourceRoot)) {
    if (!['.ts', '.js', '.mjs', '.cjs', '.svelte'].includes(extname(file))) continue;
    const source = readFileSync(file, 'utf8');
    findings.push(...findFunctionAgnosticIssues(source, file).map((finding) => `${relative(root, file)}:${finding}`));
  }
  if (findings.length) {
    console.error('Super Console core must remain function-agnostic:\n' + findings.map((finding) => `- ${finding}`).join('\n'));
    process.exitCode = 1;
  } else {
    console.log('Super Console function-agnostic source guard passed.');
  }
}
import { createUIFnError } from '../errors';

export interface RangeDefinition {
  readonly min: number;
  readonly max: number;
  readonly step?: number;
}

function decimals(value: number): number {
  const text = String(value).toLowerCase();
  const [coefficient, exponentText = '0'] = text.split('e');
  const fractionDigits = coefficient!.includes('.') ? coefficient!.length - coefficient!.indexOf('.') - 1 : 0;
  return Math.max(0, fractionDigits - Number(exponentText));
}

function roundRangeValue(value: number, precision: number): number {
  const [coefficient, exponentText = '0'] = String(value).split('e');
  const shifted = Math.round(Number(`${coefficient}e${Number(exponentText) + precision}`));
  const [rounded, roundedExponent = '0'] = String(shifted).split('e');
  return Number(`${rounded}e${Number(roundedExponent) - precision}`);
}

export function clampRangeValue(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

export function alignRangeValue(value: number, definition: RangeDefinition): number {
  const { min, max } = definition;
  const step = definition.step ?? 1;
  if (!Number.isFinite(value) || !Number.isFinite(min) || !Number.isFinite(max) || !Number.isFinite(step) || min > max || step <= 0) {
    throw createUIFnError({
      code: 'UIFN_ERR_RANGE_OUT_OF_BOUNDS',
      component: 'Range',
      message: 'Range values require finite bounds, min <= max, and a positive step.',
      details: { value, min, max, step },
    });
  }
  const precision = Math.max(decimals(min), decimals(max), decimals(step));
  const aligned = min + Math.round((clampRangeValue(value, min, max) - min) / step) * step;
  return clampRangeValue(roundRangeValue(aligned, precision), min, max);
}

export function normalizeRangeValues(values: readonly number[], definition: RangeDefinition): number[] {
  const normalized = (values.length === 0 ? [definition.min] : values)
    .map((value) => alignRangeValue(value, definition))
    .sort((left, right) => left - right);
  return normalized;
}

export function rangeValueToPercent(value: number, definition: Pick<RangeDefinition, 'min' | 'max'>): number {
  if (definition.max === definition.min) return 0;
  return clampRangeValue(((value - definition.min) / (definition.max - definition.min)) * 100, 0, 100);
}

export function rangePercentToValue(percent: number, definition: RangeDefinition): number {
  return alignRangeValue(definition.min + clampRangeValue(percent, 0, 100) / 100 * (definition.max - definition.min), definition);
}

export function stepRangeValue(value: number, key: string, definition: RangeDefinition, direction: 'ltr' | 'rtl' = 'ltr'): number {
  const step = definition.step ?? 1;
  const rtl = direction === 'rtl' ? -1 : 1;
  if (key === 'Home') return definition.min;
  if (key === 'End') return alignRangeValue(definition.max, definition);
  if (key === 'ArrowRight') return alignRangeValue(value + step * rtl, definition);
  if (key === 'ArrowLeft') return alignRangeValue(value - step * rtl, definition);
  if (key === 'ArrowUp') return alignRangeValue(value + step, definition);
  if (key === 'ArrowDown') return alignRangeValue(value - step, definition);
  if (key === 'PageUp') return alignRangeValue(value + step * 10, definition);
  if (key === 'PageDown') return alignRangeValue(value - step * 10, definition);
  return alignRangeValue(value, definition);
}
import { createUIFnError } from '@uifn/core/errors';

export type AdapterRef<TElement> =
  | ((element: TElement | null) => void)
  | { current: TElement | null }
  | null
  | undefined;

export interface ElementRegistry<TElement> {
  register: (key: string, element: TElement | null) => () => void;
  unregister: (key: string) => void;
  get: (key: string) => TElement | null;
  require: (key: string) => TElement;
  has: (key: string) => boolean;
  clear: () => void;
  entries: () => Array<[string, TElement]>;
  snapshot: () => Record<string, TElement>;
  size: () => number;
}

export function assignRef<TElement>(ref: AdapterRef<TElement>, element: TElement | null): void {
  if (!ref) {
    return;
  }

  if (typeof ref === 'function') {
    ref(element);
    return;
  }

  ref.current = element;
}

export function composeRefs<TElement>(
  ...refs: Array<AdapterRef<TElement>>
): (element: TElement | null) => void {
  return (element) => {
    refs.forEach((ref) => assignRef(ref, element));
  };
}

export function createElementRegistry<TElement>(
  options: { component?: string } = {}
): ElementRegistry<TElement> {
  const elements = new Map<string, TElement>();

  return {
    register(key, element) {
      if (element === null) {
        elements.delete(key);
      } else {
        elements.set(key, element);
      }

      return () => {
        if (element !== null && elements.get(key) === element) elements.delete(key);
      };
    },
    unregister(key) {
      elements.delete(key);
    },
    get(key) {
      return elements.get(key) ?? null;
    },
    require(key) {
      const element = elements.get(key);

      if (!elements.has(key)) {
        throw createUIFnError({
          code: 'UIFN_ERR_CONTEXT_MISSING',
          package: '@uifn/adapter-kit',
          component: options.component ?? 'ElementRegistry',
          message: 'Adapter element registry is missing a required element.',
          details: {
            key,
          },
        });
      }

      return element as TElement;
    },
    has(key) {
      return elements.has(key);
    },
    clear() {
      elements.clear();
    },
    entries() {
      return Array.from(elements.entries());
    },
    snapshot() {
      return Object.fromEntries(elements.entries());
    },
    size() {
      return elements.size;
    },
  };
}
export type LegacyAvatarStatus = 'idle' | 'loading' | 'loaded' | 'error';

export interface LegacyAvatarState {
  readonly status: LegacyAvatarStatus;
}

export interface LegacyAvatarMachine {
  readonly state: LegacyAvatarState;
  readonly actions: Readonly<{
    setLoading(): void;
    setLoaded(): void;
    setError(): void;
  }>;
  subscribe(callback: (state: LegacyAvatarState) => void): () => void;
}

/** Compatibility factory for the pre-controller Svelte adapter. */
export function createLegacyAvatar(): LegacyAvatarMachine {
  let state: LegacyAvatarState = Object.freeze({ status: 'idle' });
  const subscribers = new Set<(state: LegacyAvatarState) => void>();
  const update = (status: LegacyAvatarStatus) => {
    state = Object.freeze({ status });
    for (const subscriber of [...subscribers]) subscriber(state);
  };

  return {
    get state() {
      return state;
    },
    actions: Object.freeze({
      setLoading: () => update('loading'),
      setLoaded: () => update('loaded'),
      setError: () => update('error'),
    }),
    subscribe(callback) {
      subscribers.add(callback);
      return () => subscribers.delete(callback);
    },
  };
}
export interface AsyncListState<T> {
  readonly status: 'idle' | 'loading' | 'loaded' | 'error';
  readonly items: readonly T[];
  readonly error: unknown;
  readonly requestId: number;
}

export interface AsyncListLoadContext {
  readonly signal: AbortSignal;
  readonly filterText: string;
}

export interface AsyncList<T> {
  readonly state: AsyncListState<T>;
  load(filterText?: string): Promise<AsyncListState<T>>;
  cancel(): void;
  subscribe(callback: (state: AsyncListState<T>) => void): () => void;
  destroy(): void;
}

export function createAsyncList<T>(options: {
  readonly load: (context: AsyncListLoadContext) => Promise<readonly T[]>;
  readonly initialItems?: readonly T[];
}): AsyncList<T> {
  let state: AsyncListState<T> = Object.freeze({ status: 'idle', items: Object.freeze([...(options.initialItems ?? [])]), error: null, requestId: 0 });
  let controller: AbortController | null = null;
  let destroyed = false;
  const listeners = new Set<(state: AsyncListState<T>) => void>();
  const publish = (next: AsyncListState<T>) => {
    state = Object.freeze(next);
    listeners.forEach((listener) => {
      try {
        listener(state);
      } catch {
        // Subscriber failures are isolated from list state transitions.
      }
    });
  };
  const api: AsyncList<T> = {
    get state() { return state; },
    async load(filterText = '') {
      if (destroyed) return state;
      controller?.abort();
      controller = new AbortController();
      const requestId = state.requestId + 1;
      const active = controller;
      publish({ ...state, status: 'loading', error: null, requestId });
      try {
        const items = await options.load({ signal: active.signal, filterText });
        if (!destroyed && !active.signal.aborted && requestId === state.requestId) {
          publish({ status: 'loaded', items: Object.freeze([...items]), error: null, requestId });
        }
      } catch (error) {
        if (!destroyed && !active.signal.aborted && requestId === state.requestId) {
          publish({ ...state, status: 'error', error, requestId });
        }
      }
      return state;
    },
    cancel() {
      if (!controller || controller.signal.aborted) return;
      controller.abort();
      if (state.status === 'loading') {
        publish({
          ...state,
          status: state.items.length > 0 ? 'loaded' : 'idle',
          error: null,
          requestId: state.requestId + 1,
        });
      }
    },
    subscribe(callback) {
      if (destroyed) return () => undefined;
      listeners.add(callback);
      callback(state);
      return () => listeners.delete(callback);
    },
    destroy() {
      if (destroyed) return;
      destroyed = true;
      controller?.abort();
      listeners.clear();
    },
  };
  return api;
}
export interface LocaleMatcher {
  readonly locale: string;
  normalize(value: string): string;
  equals(left: string, right: string): boolean;
  startsWith(value: string, query: string): boolean;
  includes(value: string, query: string): boolean;
  compare(left: string, right: string): number;
}

export function createLocaleMatcher(locale = 'en'): LocaleMatcher {
  const collator = new Intl.Collator(locale, { usage: 'search', sensitivity: 'base', numeric: true });
  const normalize = (value: string) => value.normalize('NFKD').toLocaleLowerCase(locale);
  return Object.freeze({
    locale,
    normalize,
    equals: (left: string, right: string) => collator.compare(normalize(left), normalize(right)) === 0,
    startsWith(value: string, query: string) {
      const normalizedValue = Array.from(normalize(value));
      const normalizedQuery = normalize(query);
      if (normalizedQuery.length === 0) return true;
      for (let end = 1; end <= normalizedValue.length; end += 1) {
        if (collator.compare(normalizedValue.slice(0, end).join(''), normalizedQuery) === 0) return true;
      }
      return false;
    },
    includes(value: string, query: string) {
      const normalizedValue = Array.from(normalize(value));
      const normalizedQuery = normalize(query);
      if (normalizedQuery.length === 0) return true;
      for (let start = 0; start < normalizedValue.length; start += 1) {
        for (let end = start + 1; end <= normalizedValue.length; end += 1) {
          if (collator.compare(normalizedValue.slice(start, end).join(''), normalizedQuery) === 0) return true;
        }
      }
      return false;
    },
    compare: (left: string, right: string) => collator.compare(left, right),
  });
}

export function formatUIFnValueText(value: number, options: Intl.NumberFormatOptions = {}, locale = 'en'): string {
  return new Intl.NumberFormat(locale, options).format(value);
}

