    const adapter = await options.adapter(context);
    const resources = [...await options.resources(context)];
    return {
      adapter,
      resources,
      adapterInfo: {
        id: adapter.name,
        name: adapter.name,
        status: "available",
        capabilities: adapter.capabilities ?? {},
