export * from "./types.js";
export * from "./capability.js";
export * from "./adapter.js";
export * from "./client.js";
export * from "./domain-service.js";

import type { AdminCapabilityAdapter } from "@superfunctions/admin";
import { createPlugFnAdminAdapter } from "./adapter.js";
import { plugFnAdminCapability } from "./capability.js";
import { createPlugFnDomainAdminService } from "./domain-service.js";
import type { PlugFnDomainAdminServiceOptions } from "./types.js";

/** Creates the complete administration adapter from one project-owned PlugFn facade. */
export function createPlugFnDomainAdminAdapter(
  options: PlugFnDomainAdminServiceOptions,
): AdminCapabilityAdapter<typeof plugFnAdminCapability> {
  return createPlugFnAdminAdapter(createPlugFnDomainAdminService(options));
}

export const adminCapability = plugFnAdminCapability;
import type {
  ConnectionStatus,
  PlugFn,
  PlugFnOwnerKind,
  PlugFnSyncJob,
  WorkflowStatus,
} from "plugfn";
import type { AdminOperationContext } from "@superfunctions/admin";

export type PlugFnAdminJson<T> =
  T extends Date ? string
    : T extends readonly (infer TItem)[] ? PlugFnAdminJson<TItem>[]
      : T extends object ? { [TKey in keyof T]: PlugFnAdminJson<T[TKey]> }
        : T;

export interface PlugFnPageInput {
  cursor?: string;
  limit?: number;
}

export interface PlugFnProviderListInput extends PlugFnPageInput { search?: string }
export interface PlugFnProviderGetInput { id: string }
export interface PlugFnProviderView {
  id: string;
  name: string;
  displayName: string;
  description: string;
  version: string;
  iconUrl?: string;
  authType: string;
  configured: boolean;
  actions: string[];
  triggers: string[];
  webhookEvents: string[];
  syncResources: string[];
  capabilities: Record<string, boolean>;
}

export interface PlugFnConnectionListInput extends PlugFnPageInput {
  provider?: string;
  status?: ConnectionStatus;
}
export interface PlugFnConnectionGetInput { id: string }
export interface PlugFnAuthorizeConnectionInput {
  provider: string;
  redirectUri: string;
  scopes?: string[];
  connectionName?: string;
  returnTo?: string;
  prompt?: string;
  loginHint?: string;
}
export interface PlugFnConnectionTargetInput { id: string }
export interface PlugFnConnectionView {
  id: string;
  provider: string;
  ownerKind?: PlugFnOwnerKind;
  ownerId?: string;
  name?: string;
  status: ConnectionStatus;
  scopes?: string[];
  expiresAt?: string;
  connectedAt: string;
  lastUsedAt?: string;
  createdAt: string;
  updatedAt: string;
  hasCredentials: boolean;
}

export interface PlugFnInstallationListInput extends PlugFnPageInput {
  if (!job) throw new AdminError("not_found", "The PlugFn sync job was not found in the active project identity.");
  await ownedConnection(options, job.connectionId, context);
  return job;
}

/**
 * Binds the admin contract only to the public PlugFn facade. Provider secrets,
 * encrypted connection credentials, workflow handlers, webhook metadata, and
 * sync checkpoints are never projected into the administration transport.
