import { ADMIN_API_PREFIX, fetchAdmin, materializeAdminActionHref, scopedConsoleHref, withAdminScope, type AdminFetch } from './admin-api';
import {
  inferAdminResourceColumns,
  inferAdminResourceFields,
  inferAdminResourceStatus,
  inferAdminResourceTitle,
  isAdminRecord,
  moduleById,
  normalizeAdminResourceRows,
  readAdminPresentationField,
  type AdminErrorViewModel,
  type AdminResourceViewModel,
  type RegistryViewModel,
  type ResourceDetailViewModel,
  type ResourceListViewModel,
} from './view-models';

interface ResourceRouteInput {
  fetcher: AdminFetch;
  url: URL;
  registry: RegistryViewModel;
  moduleId: string;
  resourceId: string;
  sourceModuleId?: string;
}

function resourceForRoute(
  resources: AdminResourceViewModel[] | undefined,
  resourceId: string,
  sourceModuleId?: string
): AdminResourceViewModel | undefined {
  return resources?.find((candidate) => {
    const canonicalId = candidate.resourceId ?? candidate.id;
    if (sourceModuleId) {
      return candidate.sourceModuleId?.toLowerCase() === sourceModuleId.toLowerCase()
        && canonicalId.toLowerCase() === resourceId.toLowerCase();
    }
    return candidate.id.toLowerCase() === resourceId.toLowerCase()
      || (!candidate.foldedIntoModuleId && canonicalId.toLowerCase() === resourceId.toLowerCase());
  });
}

function unavailable(resourceId: string, moduleId: string): AdminErrorViewModel {
  return {
    status: 404,
    code: 'RESOURCE_NOT_ENABLED',
    message: `${resourceId} is not an enabled ${moduleId} administration resource.`,
  };
}

function parseQueryValue(raw: string, schema: AdminResourceViewModel['listInputSchema']): unknown {
  const types = schema?.type ? (Array.isArray(schema.type) ? schema.type : [schema.type]) : [];
  if (types.includes('null') && raw === 'null') return null;
  if (types.includes('integer') || types.includes('number')) {
    const parsed = Number(raw);
    return Number.isFinite(parsed) ? parsed : raw;
  }
  if (types.includes('boolean')) return raw === 'true' ? true : raw === 'false' ? false : raw;
  if (types.includes('object') || types.includes('array')) {
    try { return JSON.parse(raw); } catch { return raw; }
  }
  return raw;
}

function inputSchemaAtPath(
  schema: AdminResourceViewModel['listInputSchema'],
  path: string,
): AdminResourceViewModel['listInputSchema'] {
  let current = schema;
  for (const segment of path.split('.')) {
    if (!current) return undefined;
    const types = current.type ? (Array.isArray(current.type) ? current.type : [current.type]) : [];
    if (!types.includes('object')) return undefined;
    current = current.properties?.[segment];
  }
  return current;
}

function setInputPath(target: Record<string, unknown>, path: string, value: unknown): void {
  const segments = path.split('.');
  if (segments.some((segment) => segment === '__proto__' || segment === 'prototype' || segment === 'constructor')) {
    throw new Error('Administration input paths cannot address object prototype properties.');
  }
  let current = target;
  segments.forEach((segment, index) => {
    if (index === segments.length - 1) {
      current[segment] = value;
      return;
    }
    const existing = current[segment];
    if (!isAdminRecord(existing)) current[segment] = Object.create(null) as Record<string, unknown>;
    current = current[segment] as Record<string, unknown>;
  });
}

function listRequestHref(
  resource: AdminResourceViewModel,
  apiHref: string,
  searchParams: URLSearchParams,
): string {
  const requestHref = new URL(apiHref, 'http://superconsole.local');
  const schema = resource.listInputSchema;
  const input: Record<string, unknown> = {};
  for (const [key, raw] of searchParams) {
    const property = schema?.type === 'object' ? schema.properties?.[key] : undefined;
    if (property) input[key] = parseQueryValue(raw, property);
  }
  const searchPath = resource.presentation?.query?.searchInputPath
    ?? (schema?.type === 'object' && schema.properties?.search ? 'search' : undefined);
  const query = searchParams.get('q');
  if (searchPath && query) setInputPath(input, searchPath, query);
  for (const filter of resource.presentation?.query?.filters ?? []) {
    const raw = searchParams.get(filter.field);
    if (raw !== null && raw !== '') {
      setInputPath(input, filter.inputPath, parseQueryValue(raw, inputSchemaAtPath(schema, filter.inputPath)));
    }
  }
  for (const [key, value] of Object.entries(input)) {
    requestHref.searchParams.set(key, typeof value === 'string' ? value : JSON.stringify(value));
  }
  return `${requestHref.pathname}${requestHref.search}`;
}

function relatedResources(
  module: NonNullable<ReturnType<typeof moduleById>>,
  resource: AdminResourceViewModel,
  item: Record<string, unknown> | undefined,
  searchParams: URLSearchParams,
) {
  if (!item) return [];
  const canonicalResource = resource.resourceId ?? resource.id;
  return (module.resources ?? []).flatMap((candidate) => {
    const parent = candidate.presentation?.parent;
    if (!parent || parent.resourceId !== canonicalResource || candidate.sourceModuleId !== resource.sourceModuleId) return [];
    const href = new URL(candidate.href, 'http://superconsole.local');
    for (const binding of parent.bindings) {
      const value = readAdminPresentationField(item, binding.sourceField);
      if (value === undefined || value === null || value === '') return [];
      href.searchParams.set(binding.queryField, typeof value === 'string' ? value : JSON.stringify(value));
    }
    return [{
      resourceId: candidate.resourceId ?? candidate.id,
      label: candidate.pluralLabel ?? candidate.label,
      description: candidate.description,
      href: scopedConsoleHref(`${href.pathname}${href.search}`, searchParams),
    }];
  });
}

function detailInput(
  resource: AdminResourceViewModel,
  identity: string,
  searchParams: URLSearchParams
): { value?: Record<string, unknown>; missing?: string } {
  const idInput = resource.detailIdInput ?? 'id';
  const value: Record<string, unknown> = { [idInput]: identity };
  const schema = resource.detailInputSchema;
  const required = schema?.type === 'object' ? schema.required ?? [] : [];
  for (const key of required) {
    if (key === idInput) continue;
    const raw = searchParams.get(key);
    if (raw === null || raw === '') return { missing: key };
    const property = schema?.type === 'object' ? schema.properties?.[key] : undefined;
    if (!property || property.type === 'string') {
      value[key] = raw;
      continue;
    }
    try {
      value[key] = JSON.parse(raw);
    } catch {
      return { missing: key };
    }
  }
  return { value };
}

export async function loadResourceList(input: ResourceRouteInput): Promise<{
  view?: ResourceListViewModel;
  loadError?: AdminErrorViewModel;
  query: string;
    href: navigation?.path ?? `/modules/${manifest.id}`,
    group: navigation?.group ?? manifest.category,
    enabled: true,
    visibleInNavigation: manifest.availability !== 'nested',
    parentModuleId: manifest.owner?.moduleId,
    health: 'unknown',
    healthLabel: manifest.health ? 'Health available' : 'No health operation declared',
    version: manifest.version,
    capabilities: [...entries.map((entry) => entry.operation.id), ...childViews.flatMap(({ view }) => view.capabilities)],
    resources: [...ownResources, ...foldedResources],
    actions: [...entries
      .filter((entry) => entry.operation.safety.classification !== 'read' && entry.operation.target?.collection === true)
      .map(actionView), ...foldedActions],
    foldedModuleIds: childViews.map(({ view }) => view.id),
    manifest,
  };
}

function parseScalar(schema: AdminJsonSchema | undefined, raw: string): unknown {
  const types = schema?.type ? (Array.isArray(schema.type) ? schema.type : [schema.type]) : [];
  if (types.includes('integer') || types.includes('number')) return Number(raw);
  if (types.includes('boolean')) return raw === 'true' ? true : raw === 'false' ? false : raw;
  if (types.includes('array') || types.includes('object')) {
    try { return JSON.parse(raw); } catch { return raw; }
  }
  return raw;
}

function extractPathParams(entry: AdminRegistryOperation, concretePath: string): Record<string, string> {
  const pattern = entry.routePath.split('/').filter(Boolean);
  const concrete = concretePath.split('?')[0]!.split('/').filter(Boolean);
  const params: Record<string, string> = {};
  pattern.forEach((part, index) => {
    const match = /^:([A-Za-z_][A-Za-z0-9_]*)$/.exec(part) ?? /^\{([A-Za-z_][A-Za-z0-9_]*)\}$/.exec(part);
    if (match && concrete[index] !== undefined) params[match[1]!] = decodeURIComponent(concrete[index]!);
  });
  return params;
}

async function operationInput(request: Request, entry: AdminRegistryOperation, matchedPath: string): Promise<Record<string, unknown>> {
  const schema = entry.operation.inputSchema;
  const input: Record<string, unknown> = {};
  if (request.method === 'GET' || request.method === 'DELETE') {
    const url = new URL(request.url);
    url.searchParams.forEach((value, key) => {
      if (['installationId', 'organizationId', 'workspaceId', 'projectId', 'environmentId', 'installation', 'organization', 'workspace', 'project', 'environment', 'namespace', 'region'].includes(key)) return;
      const canonicalKey = key === 'q' && schema?.properties?.search ? 'search' : key;
      input[canonicalKey] = parseScalar(schema?.properties?.[canonicalKey], value);
    });
  } else {
    const text = await request.text();
    if (text.trim()) {
      let body: unknown;
      try { body = JSON.parse(text); } catch { throw new SuperConsoleHttpError('The request body must be valid JSON.', { status: 400, code: 'INVALID_JSON' }); }
      if (!body || typeof body !== 'object' || Array.isArray(body)) throw new SuperConsoleHttpError('The request body must be a JSON object.', { status: 400, code: 'INVALID_BODY' });
      Object.assign(input, body);
    }
  }
  const params = extractPathParams(entry, matchedPath);
  for (const [key, value] of Object.entries(params)) input[key] = parseScalar(schema?.properties?.[key], value);
  return input;
}

function resultResponse(result: AdminResult): Response {
  const status = result.ok === false ? result.error.status : 200;
  return response(result, status, result.requestId ? { 'x-request-id': result.requestId } : undefined);
}

export class SuperConsole {
  readonly registry;
  readonly dispatcher: AdminDispatcher;
  readonly openApi;
  readonly mcpTools;
  readonly mcpServer;
  private readonly options: SuperConsoleOptions;
  private readonly now: () => Date;
  private mcpHandlerPromise?: Promise<SuperConsoleMcpHandler>;

  constructor(options: SuperConsoleOptions) {
    if (options.apiBasePath !== undefined && options.apiBasePath !== '/api/admin/v1') {
      throw new Error('The bundled Super Console UI currently requires apiBasePath to be /api/admin/v1.');

  private async moduleRequest(request: Request, relative: string, state: SuperConsoleRequestState): Promise<Response> {
    const [, encodedModuleId, ...rest] = relative.split('/');
    const moduleId = decodeURIComponent(encodedModuleId ?? '');
    if (!this.registry.hasModule(moduleId)) throw new SuperConsoleHttpError(`${moduleId || 'The requested module'} is not enabled.`, { status: 404, code: 'MODULE_NOT_ENABLED' });
    if (rest.length === 0 && (request.method === 'GET' || request.method === 'HEAD')) {
      await this.authorizeShell('registry', state);
      const manifest = this.registry.requireManifest(moduleId);
      const view = await this.moduleViewFor(manifest, state);
      if (view.capabilities.length === 0) {
        throw new SuperConsoleHttpError('No module capabilities are visible to the active operator.', { status: 404, code: 'MODULE_NOT_ENABLED' });
      }
      return this.headAware(request, success({
        module: view,
        summary: [
          { id: 'resources', label: 'Resources', value: view.resources.length },
          { id: 'operations', label: 'Operations', value: view.capabilities.length },
        ],
        notices: [],
      }, state.context.requestId));
    }

    const url = new URL(request.url);
    let matchedPath = url.pathname;
    const resourceAliasPath = rest[0] !== 'resources'
      ? `${this.registry.apiBasePath}/modules/${encodeURIComponent(moduleId)}/resources/${rest.join('/')}`
      : undefined;
    const routeMethod = request.method === 'HEAD' ? 'GET' : request.method;
    let entry = this.registry.matchRoute(routeMethod, matchedPath);
    if (!entry && resourceAliasPath) {
      entry = this.registry.matchRoute(routeMethod, resourceAliasPath);
      if (entry) matchedPath = resourceAliasPath;
    }
    if (!entry) {
      const methodExists = this.registry.operations.some((candidate) => candidate.moduleId === moduleId &&
        [matchedPath, resourceAliasPath].filter((path): path is string => Boolean(path)).some((path) =>
          this.registry.matchRoute(routeDefinition(candidate.operation).method, path)?.operation.id === candidate.operation.id));
      if (methodExists) throw new SuperConsoleHttpError('This module operation does not support the requested method.', { status: 405, code: 'METHOD_NOT_ALLOWED' });
    }
    if (!entry || entry.moduleId !== moduleId) throw new SuperConsoleHttpError('The requested module operation is not enabled.', { status: 404, code: 'OPERATION_NOT_ENABLED' });
    if (!(await this.operationDiscoverable(entry, state))) {
      throw new SuperConsoleHttpError('The requested module operation is not enabled.', { status: 404, code: 'OPERATION_NOT_ENABLED' });
    }
    if (entry.operation.safety.classification !== 'read' && READ_METHODS.has(request.method)) {
      await this.options.auth.authorizeMutation?.({ principal: state.principal, request });
    }
    const input = await operationInput(request, entry, matchedPath);
    const dispatched = await this.dispatcher.dispatch({ operationId: entry.operation.id, input, context: state.context });
    return this.headAware(request, resultResponse(dispatched));
  }

  private requirePermission(principal: SuperConsolePrincipal, permission: string): void {
    if (!this.hasPermission(principal.actor.permissions, permission)) {
      throw new SuperConsoleHttpError('The active operator lacks the required permission.', { status: 403, code: 'PERMISSION_DENIED' });
    }
  }

  private hasPermission(permissions: readonly string[] | undefined, permission: string): boolean {
    return Boolean(permissions?.includes('*') || permissions?.includes(permission));
  }

  private async authorizeShell(surface: 'registry' | 'overview' | 'api' | 'mcp' | 'settings' | 'audit' | 'search', state: SuperConsoleRequestState): Promise<void> {
    if (!(await this.options.shellPolicy.authorize({ surface, principal: state.principal, context: state.context }))) {
      throw new SuperConsoleHttpError('The active operator cannot access this administration surface.', { status: 403, code: 'PERMISSION_DENIED' });
    }
  }
import type { AdminCapabilityAdapter } from "@superfunctions/admin";
import {
  createSuperConsole,
  type SuperConsole,
  type SuperConsoleOptions,
} from "../src/lib/server/index.js";

export const DEV_ENABLED_ADMIN_MODULE_IDS = [
  "apifn",
  "authfn",
  "billfn",
  "botfn",
  "datafn",
  "filefn",
  "hostfn",
  "plugfn",
  "searchfn",
] as const;

export const DEV_UNAVAILABLE_ADMIN_MODULE_IDS = ["clifn", "extfn"] as const;

export const DEV_REGISTERED_ADMIN_MODULE_IDS = [
  ...DEV_ENABLED_ADMIN_MODULE_IDS,
  ...DEV_UNAVAILABLE_ADMIN_MODULE_IDS,
] as const;

export type DevAdminModuleId = (typeof DEV_REGISTERED_ADMIN_MODULE_IDS)[number];

export type DevAdminAdapters = Readonly<Record<DevAdminModuleId, AdminCapabilityAdapter>>;

export interface DevAdminSelection {
  adapters: readonly AdminCapabilityAdapter[];
  enabledModules: readonly (typeof DEV_ENABLED_ADMIN_MODULE_IDS)[number][];
}

/**
 * The representative `dev` composition is an explicit allowlist. CliFn and
 * ExtFn remain registered so discovery can explain why they are unavailable,
 * but they are never enabled without a domain-backed operator service.
 */
export function selectDevAdminAdapters(adapters: DevAdminAdapters): DevAdminSelection {
  const registered = DEV_REGISTERED_ADMIN_MODULE_IDS.map((moduleId) => {
    const adapter = adapters[moduleId];
    if (adapter.manifest.id !== moduleId) {
      throw new Error(`The dev admin adapter registered as ${moduleId} exposes manifest ${adapter.manifest.id}.`);
    }
    return adapter;
  });

  for (const moduleId of DEV_ENABLED_ADMIN_MODULE_IDS) {
    if (adapters[moduleId].manifest.availability === "unavailable") {
      throw new Error(`The dev admin module ${moduleId} cannot be enabled without a domain-backed service.`);
    }
  }
  for (const moduleId of DEV_UNAVAILABLE_ADMIN_MODULE_IDS) {
    if (adapters[moduleId].manifest.availability !== "unavailable") {
      throw new Error(`The dev admin module ${moduleId} must remain explicitly unavailable until it has a safe operator service.`);
    }
  }

  return {
    adapters: registered,
    enabledModules: DEV_ENABLED_ADMIN_MODULE_IDS,
  };
}

export type DevSuperConsoleOptions = Omit<SuperConsoleOptions, "adapters" | "enabledModules"> & {
  adapters: DevAdminAdapters;
};

/** Compose this from real function-owned adapters and deployment-owned infrastructure. */
export function createDevSuperConsoleInstallation(options: DevSuperConsoleOptions): SuperConsole {
  const { adapters, ...infrastructure } = options;
  return createSuperConsole({
    ...infrastructure,
    ...selectDevAdminAdapters(adapters),
  });
}
import { getSuperConsole, loadSuperConsoleInstallation } from './installation.js';

export async function bootConfiguredSuperConsole(specifier?: string): Promise<void> {
  if (getSuperConsole()) return;
  if (!specifier?.trim()) return;
  // Installation import and composition validation are startup-fatal by design.
  await loadSuperConsoleInstallation(specifier);
}

export async function handleConfiguredSuperConsole(request: Request): Promise<Response> {
  const console = getSuperConsole();
  if (!console) {
    return new Response(JSON.stringify({
      ok: false,
      error: {
        code: 'SUPERCONSOLE_NOT_CONFIGURED',
        message: 'Super Console has not been composed for this server process.',
        status: 503,
      },
    }), {
      status: 503,
      headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' },
    });
  }
  return console.handle(request);
}
