#!/usr/bin/env node

import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { build as buildWithTsup } from 'tsup';

const packageRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const outputRoot = path.join(packageRoot, 'dist');

// Build-only bridge for the published @uifn/svelte@0.0.1 primitive entries.
// These names are intentionally absent from the @uifn/core public root.
const legacyRuntimeAliases = Object.freeze({
  accordion: 'createAccordion',
  'alert-dialog': 'createAlertDialog',
  avatar: 'createAvatar',
  checkbox: 'createCheckbox',
  combobox: 'createCombobox',
  'context-menu': 'createContextMenu',
  dialog: 'createDialog',
  'hover-card': 'createHoverCard',
  popover: 'createPopover',
  progress: 'createProgress',
  'radio-group': 'createRadioGroup',
  select: 'createSelect',
  slider: 'createSlider',
  switch: 'createSwitch',
  toast: 'createToast',
  toggle: 'createToggle',
  'toggle-group': 'createToggleGroup',
  tooltip: 'createTooltip',
});

function primitiveMetadata() {
  const catalogPath = path.resolve(packageRoot, '..', 'catalog', 'generated', 'catalog.json');
  const catalog = JSON.parse(readFileSync(catalogPath, 'utf8'));
  return catalog.primitives.map((primitive) => {
    const interactive = primitive.implementationKind === 'interactive-controller';
    return {
      id: primitive.id,
      input: primitive.name === 'HoverCard'
        ? 'CreateHoverCardProps'
        : `${primitive.name}Props`,
      runtime: interactive
        ? `create${primitive.name}Controller`
        : `${primitive.name}Contract`,
      secondaryType: interactive
        ? `${primitive.name}Controller`
        : `${primitive.name}ContractParts`,
      legacyRuntime: primitive.id === 'avatar'
        ? 'createLegacyAvatar'
        : primitive.id === 'progress'
          ? 'createProgressController'
          : undefined,
      legacyAlias: legacyRuntimeAliases[primitive.id],
    };
  }).concat([
    {
      id: 'dropdown-menu',
      input: 'MenuProps',
      runtime: 'createMenuController',
      secondaryType: 'MenuController',
      legacyAlias: 'createDropdownMenu',
    },
    {
      id: 'menu-bar',
      input: 'MenubarProps',
      runtime: 'createMenubarController',
      secondaryType: 'MenubarController',
      legacyAlias: 'createMenuBar',
    },
  ]);
}

async function writePrimitiveEntries(primitives) {
  const entryDirectory = path.join(outputRoot, 'primitive-entries');
  mkdirSync(entryDirectory, { recursive: true });
  const temporaryRoot = mkdtempSync(path.join(tmpdir(), 'uifn-core-primitive-entries-'));
  try {
    for (const primitive of primitives) {
      const temporaryEntry = path.join(temporaryRoot, `${primitive.id}.ts`);
      const legacyRuntime = primitive.legacyRuntime ?? primitive.runtime;
      const runtimeExports = primitive.legacyAlias
        ? `${primitive.runtime}, ${legacyRuntime} as ${primitive.legacyAlias}`
        : primitive.runtime;
      writeFileSync(
        temporaryEntry,
        `export { ${runtimeExports} } from ${JSON.stringify(path.join(packageRoot, 'src/primitives/index.ts'))};\n`,
      );
      await buildWithTsup({
        entry: { [`primitive-entries/${primitive.id}`]: temporaryEntry },
        outDir: outputRoot,
        format: ['cjs', 'esm'],
        outExtension({ format }) {
          return { js: format === 'esm' ? '.mjs' : '.js' };
        },
        dts: false,
        clean: false,
        splitting: false,
        sourcemap: true,
        bundle: true,
        treeshake: true,
        minify: false,
        platform: 'neutral',
        target: 'es2020',
        define: { __UIFN_DEV_TRACE__: 'false' },
        silent: true,
      });
      writeFileSync(
        path.join(entryDirectory, `${primitive.id}.d.ts`),
        `export { ${runtimeExports}, type ${primitive.input}, type ${primitive.secondaryType} } from '../primitives/index';\n`,
      );
    }
  } finally {
    rmSync(temporaryRoot, { recursive: true, force: true });
  }
}

async function verifyLegacyPrimitiveEntries(primitives) {
  for (const primitive of primitives) {
    if (!primitive.legacyAlias) continue;
    const entryPath = path.join(outputRoot, 'primitive-entries', `${primitive.id}.mjs`);
    const entry = await import(pathToFileURL(entryPath).href);
    if (typeof entry[primitive.legacyAlias] !== 'function') {
      throw new Error(`Primitive entry ${primitive.id} must export function ${primitive.legacyAlias}.`);
    }
  }
}
import { createUIFnError } from '../errors';

const TOKEN_SANITIZER = /[^a-z0-9-]+/g;
const REPEATED_DASHES = /-+/g;

/** Canonical normalization for every public, collection, and part ID segment. */
export function normalizeUIFnToken(token: string): string {
  return token
    .normalize('NFKD')
    .trim()
    .toLowerCase()
    .replace(TOKEN_SANITIZER, '-')
    .replace(REPEATED_DASHES, '-')
    .replace(/^-|-$/g, '');
}

export function composeUIFnScopedId(...segments: readonly string[]): string {
  const normalized = segments.map(normalizeUIFnToken).filter(Boolean);
  if (normalized.length !== segments.length || normalized.length === 0) {
    throw createUIFnError({
      code: 'UIFN_CORE_ENVIRONMENT_INVALID',
      component: 'Id',
      message: 'Canonical IDs MUST contain only non-empty normalized segments.',
      details: { segments },
    });
  }
  return normalized.join('-');
}

function encodeUIFnDynamicSegment(value: string): string {
  const bytes = new TextEncoder().encode(value);
  return `key-${Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('')}`;
}

export function createUIFnPartId(scopeId: string, component: string, part: string, key?: string | number): string {
  return composeUIFnScopedId(
    scopeId,
    component,
    part,
    ...(key === undefined ? [] : [encodeUIFnDynamicSegment(String(key))]),
  );
}
import type { CollectionKey, ListCollection } from './collection';

export type SelectionMode = 'none' | 'single' | 'multiple';
export type SelectionBehavior = 'replace' | 'toggle';

export interface ListSelection<TKey extends CollectionKey> {
  readonly mode: SelectionMode;
  readonly behavior: SelectionBehavior;
  readonly selectedKeys: ReadonlySet<TKey>;
  readonly anchorKey: TKey | null;
  readonly currentKey: TKey | null;
}

function createReadonlySet<TKey>(values: Iterable<TKey>): ReadonlySet<TKey> {
  const set = new Set(values);
  let facade: ReadonlySet<TKey>;
  facade = {
    get size() { return set.size; },
    has: (value) => set.has(value),
    entries: () => set.entries(),
    keys: () => set.keys(),
    values: () => set.values(),
    forEach(callback, thisArg) {
      set.forEach((value) => callback.call(thisArg, value, value, facade));
    },
    [Symbol.iterator]: () => set[Symbol.iterator](),
  };
  return Object.freeze(facade);
}

export function createListSelection<TKey extends CollectionKey>(options: {
  readonly mode?: SelectionMode;
  readonly behavior?: SelectionBehavior;
  readonly selectedKeys?: Iterable<TKey>;
  readonly anchorKey?: TKey | null;
  readonly currentKey?: TKey | null;
} = {}): ListSelection<TKey> {
  const mode = options.mode ?? 'single';
  const selected = [...(options.selectedKeys ?? [])];
  return Object.freeze({
    mode,
    behavior: options.behavior ?? 'replace',
    selectedKeys: createReadonlySet(mode === 'none' ? [] : mode === 'single' ? selected.slice(0, 1) : selected),
    anchorKey: options.anchorKey ?? null,
    currentKey: options.currentKey ?? null,
  });
}

export function selectCollectionKey<T, TKey extends CollectionKey>(
  collection: ListCollection<T, TKey>,
  selection: ListSelection<TKey>,
  key: TKey,
): ListSelection<TKey> {
  if (selection.mode === 'none' || collection.isDisabled(key) || !collection.keys.includes(key)) return selection;
  const selected = new Set(selection.selectedKeys);
  if (selection.mode === 'single' || selection.behavior === 'replace') selected.clear();
  if (selection.mode === 'multiple' && selection.behavior === 'toggle' && selected.has(key)) selected.delete(key);
  else selected.add(key);
  return createListSelection({ ...selection, selectedKeys: selected, anchorKey: key, currentKey: key });
}

export function selectCollectionRange<T, TKey extends CollectionKey>(
  collection: ListCollection<T, TKey>,
  selection: ListSelection<TKey>,
  toKey: TKey,
): ListSelection<TKey> {
  if (!collection.keys.includes(toKey)) return selection;
  if (selection.mode !== 'multiple' || collection.isDisabled(toKey)) return selectCollectionKey(collection, selection, toKey);
  const anchor = selection.anchorKey !== null && collection.keys.includes(selection.anchorKey) ? selection.anchorKey : toKey;
  const [start, end] = [collection.indexOf(anchor), collection.indexOf(toKey)].sort((a, b) => a - b);
  const selected = new Set(selection.behavior === 'replace' ? [] : selection.selectedKeys);
  collection.keys.slice(start, end + 1).forEach((key) => {
    if (!collection.isDisabled(key)) selected.add(key);
  });
  return createListSelection({ ...selection, selectedKeys: selected, anchorKey: anchor, currentKey: toKey });
}

export function reconcileListSelection<T, TKey extends CollectionKey>(
  collection: ListCollection<T, TKey>,
  selection: ListSelection<TKey>,
): ListSelection<TKey> {
  const selected = [...selection.selectedKeys].filter((key) => collection.keys.includes(key) && !collection.isDisabled(key));
  return createListSelection({
    ...selection,
    selectedKeys: selected,
    anchorKey: selection.anchorKey !== null && collection.keys.includes(selection.anchorKey) ? selection.anchorKey : null,
    currentKey: selection.currentKey !== null && collection.enabledKeys.includes(selection.currentKey) ? selection.currentKey : null,
  });
}
export interface LocaleMatcher {
  readonly locale: string;
  normalize(value: string): string;
