import type { CallToolResult } from "@modelcontextprotocol/sdk/types.js";

function jsonSafe(value: unknown): unknown {
  const seen = new WeakSet<object>();
  try {
    const serialized = JSON.stringify(value, (_key, entry: unknown) => {
      if (typeof entry === "bigint") return entry.toString();
      if (entry && typeof entry === "object") {
        if (seen.has(entry)) return "[Circular]";
        seen.add(entry);
      }
      return entry;
    });
    return serialized === undefined ? String(value) : JSON.parse(serialized) as unknown;
  } catch {
    return "[Unserializable]";
  }
}

export class McpFnError extends Error {
  readonly code: string;
  readonly details?: unknown;

  constructor(code: string, message: string, details?: unknown) {
    super(message);
    this.name = "McpFnError";
    this.code = code;
    this.details = details;
  }
}

export class McpFnValidationError extends McpFnError {
  constructor(message: string, details?: unknown) {
    super("MCPFN_INVALID_ARGUMENTS", message, details);
    this.name = "McpFnValidationError";
  }
}

export class McpFnOutputValidationError extends McpFnError {
  constructor(message: string, details?: unknown) {
    super("MCPFN_INVALID_OUTPUT", message, details);
    this.name = "McpFnOutputValidationError";
  }
}

export function errorResult(
  error: unknown,
  options: { includeStructuredContent?: boolean } = {},
): CallToolResult {
  const normalized =
    error instanceof McpFnError
      ? { code: error.code, message: error.message, details: error.details }
      : error instanceof Error && "code" in error && typeof error.code === "string"
        ? {
            code: error.code,
            message: error.message,
            details:
              "details" in error
                ? error.details
                : "metadata" in error
                  ? error.metadata
                  : undefined,
          }
      : error && typeof error === "object" &&
          "code" in error && typeof error.code === "string" &&
          "message" in error && typeof error.message === "string"
        ? {
            code: error.code,
            message: error.message,
            details:
              "details" in error
                ? error.details
                : "metadata" in error
                  ? error.metadata
                  : undefined,
          }
      : {
          code: "MCPFN_TOOL_ERROR",
          message: error instanceof Error ? error.message : String(error),
        };
  const structuredContent = {
    ok: false,
    error: Object.fromEntries(
      Object.entries(normalized)
        .filter(([, value]) => value !== undefined)
        .map(([key, value]) => [key, key === "details" ? jsonSafe(value) : value]),
    ),
  } as { ok: false; error: Record<string, unknown> };
  return {
    content: [{ type: "text", text: JSON.stringify(structuredContent, null, 2) }],
    ...(options.includeStructuredContent === false ? {} : { structuredContent }),
    isError: true,
  };
}
import { createHash } from "node:crypto";

export function compareCodeUnits(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function canonicalizeValue(value: unknown, key: string, applyToJSON: boolean): unknown {
  if (applyToJSON && value && typeof value === "object" && "toJSON" in value) {
    const toJSON = (value as { toJSON?: unknown }).toJSON;
    if (typeof toJSON === "function") {
      return canonicalizeValue(toJSON.call(value, key), key, false);
    }
  }
  if (Array.isArray(value)) {
    return Array.from({ length: value.length }, (_, index) => canonicalizeValue(value[index], String(index), true));
  }
  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>)
        .filter(([, entry]) => entry !== undefined)
        .sort(([left], [right]) => compareCodeUnits(left, right))
        .map(([property, entry]) => [property, canonicalizeValue(entry, property, true)]),
    );
  }
  return value;
}

export function canonicalize(value: unknown): unknown {
  return canonicalizeValue(value, "", true);
}

export function canonicalJson(value: unknown): string {
  const seen = new Set<object>();
  const serialize = (entry: unknown, key: string, applyToJSON = true): string | undefined => {
    if (applyToJSON && entry && typeof entry === "object" && "toJSON" in entry) {
      const toJSON = (entry as { toJSON?: unknown }).toJSON;
      if (typeof toJSON === "function") return serialize(toJSON.call(entry, key), key, false);
    }
    if (entry === null || typeof entry !== "object") return JSON.stringify(entry);
    if (seen.has(entry)) throw new TypeError("Cannot canonicalize a circular value.");
    seen.add(entry);
    try {
      if (Array.isArray(entry)) {
        const items = Array.from({ length: entry.length }, (_, index) => serialize(entry[index], String(index)) ?? "null");
        return `[${items.join(",")}]`;
      }
      const properties = Object.entries(entry as Record<string, unknown>)
        .filter(([, item]) => item !== undefined)
        .sort(([left], [right]) => compareCodeUnits(left, right))
        .flatMap(([key, item]) => {
          const serialized = serialize(item, key);
          return serialized === undefined ? [] : [`${JSON.stringify(key)}:${serialized}`];
        });
      return `{${properties.join(",")}}`;
    } finally {
      seen.delete(entry);
    }
  };
  const serialized = serialize(value, "");
  return serialized as string;
}

export function sha256(value: unknown): string {
  return createHash("sha256").update(canonicalJson(value)).digest("hex");
