  7	function canonicalizeValue(value: unknown, key: string, applyToJSON: boolean): unknown {
  8	  if (applyToJSON && value && typeof value === "object" && "toJSON" in value) {
  9	    const toJSON = (value as { toJSON?: unknown }).toJSON;
 10	    if (typeof toJSON === "function") {
 11	      return canonicalizeValue(toJSON.call(value, key), key, false);
 12	    }
 13	  }
 14	  if (Array.isArray(value)) {
 15	    return Array.from({ length: value.length }, (_, index) => canonicalizeValue(value[index], String(index), true));
 16	  }
 17	  if (value && typeof value === "object") {
 18	    return Object.fromEntries(
 19	      Object.entries(value as Record<string, unknown>)
 20	        .filter(([, entry]) => entry !== undefined)
 21	        .sort(([left], [right]) => compareCodeUnits(left, right))
 22	        .map(([property, entry]) => [property, canonicalizeValue(entry, property, true)]),
 23	    );
 24	  }
 25	  return value;
 26	}
