 32	export function canonicalJson(value: unknown): string {
 33	  const seen = new Set<object>();
 34	  const serialize = (entry: unknown, key: string, applyToJSON = true): string | undefined => {
 35	    if (applyToJSON && entry && typeof entry === "object" && "toJSON" in entry) {
 36	      const toJSON = (entry as { toJSON?: unknown }).toJSON;
 37	      if (typeof toJSON === "function") return serialize(toJSON.call(entry, key), key, false);
 38	    }
 39	    if (entry === null || typeof entry !== "object") return JSON.stringify(entry);
 40	    if (seen.has(entry)) throw new TypeError("Cannot canonicalize a circular value.");
 41	    seen.add(entry);
 42	    try {
 43	      if (Array.isArray(entry)) {
 44	        const items = Array.from({ length: entry.length }, (_, index) => serialize(entry[index], String(index)) ?? "null");
 45	        return `[${items.join(",")}]`;
 46	      }
 47	      const properties = Object.entries(entry as Record<string, unknown>)
 48	        .filter(([, item]) => item !== undefined)
 49	        .sort(([left], [right]) => compareCodeUnits(left, right))
 50	        .flatMap(([key, item]) => {
 51	          const serialized = serialize(item, key);
 52	          return serialized === undefined ? [] : [`${JSON.stringify(key)}:${serialized}`];
 53	        });
 54	      return `{${properties.join(",")}}`;
 55	    } finally {
 56	      seen.delete(entry);
 57	    }
 58	  };
 59	  const serialized = serialize(value, "");
 60	  return serialized as string;
 61	}
