 193	  private async withWebhookReceiptClaimLock<T>(key: string, work: () => Promise<T>): Promise<T> {
 194	    const previous = this.webhookReceiptClaimLocks.get(key) ?? Promise.resolve();
 195	    let release!: () => void;
 196	    const current = new Promise<void>((resolve) => {
 197	      release = resolve;
 198	    });
 199	    const tail = previous.catch(() => {}).then(() => current);
 200	    this.webhookReceiptClaimLocks.set(key, tail);
 201	
 202	    await previous.catch(() => {});
 203	    try {
 204	      return await work();
 205	    } finally {
 206	      release();
 207	      if (this.webhookReceiptClaimLocks.get(key) === tail) {
 208	        this.webhookReceiptClaimLocks.delete(key);
 209	      }
 210	    }
 211	  }
