 224	  async updateWebhookReceipt(
 225	    id: string,
 226	    updates: Partial<PlugFnWebhookReceipt>
 227	  ): Promise<PlugFnWebhookReceipt> {
 228	    const normalizedUpdates = { ...updates };
 229	    if (updates.metadata !== undefined) {
 230	      const metadata: Record<string, unknown> = {};
 231	      for (const [key, value] of Object.entries(updates.metadata ?? {})) {
 232	        if (value === undefined) {
 233	          continue;
 234	        }
 235	        metadata[key] = value;
 236	      }
 237	      // Receipt metadata uses replacement semantics. Avoid a cross-instance
 238	      // read/merge/write race and always preserve the runtime-owned timestamp.
 239	      metadata.updatedAt = new Date().toISOString();
 240	      normalizedUpdates.metadata = metadata;
 241	    }
 242	    return this.adapter.updateWebhookReceipt(id, normalizedUpdates);
 243	  }
