import { describe, expect, it, vi } from 'vitest';
import { loadResourceDetail, loadResourceList } from '../../src/lib/components/resource-pages';
import { normalizeAdminResourceRows, type RegistryViewModel } from '../../src/lib/components/view-models';

const registry: RegistryViewModel = {
  modules: [{
    id: 'examplefn',
    name: 'ExampleFn',
    description: 'Example resources.',
    href: '/modules/examplefn',
    enabled: true,
    resources: [{
      id: 'records',
      resourceId: 'records',
      sourceModuleId: 'examplefn',
      idField: 'id',
      label: 'Records',
      href: '/modules/examplefn/records',
      listApiHref: '/api/admin/v1/modules/examplefn/resources/records',
      presentation: {
        columns: [{ field: 'createdAt', label: 'Created' }],
        defaultSort: { field: 'createdAt', direction: 'desc' },
      },
    }],
  }],
};

describe('generic resource list ordering', () => {
  it('preserves provider ordering for canonical items and explicit rows', async () => {
    const payloads = [
      { items: [{ id: 'provider-first', createdAt: '2024-01-01' }, { id: 'provider-second', createdAt: '2026-01-01' }] },
      { rows: [{ id: 'explicit-first', values: { createdAt: '2024-01-01' } }, { id: 'explicit-second', values: { createdAt: '2026-01-01' } }] },
    ];
    const fetcher = vi.fn(async () => new Response(JSON.stringify({ ok: true, data: payloads.shift() }), {
      status: 200,
      headers: { 'content-type': 'application/json' },
    }));
    const input = {
      fetcher,
      url: new URL('https://console.example.test/modules/examplefn/records'),
      registry,
      moduleId: 'examplefn',
      resourceId: 'records',
    };

    const canonical = await loadResourceList(input);
    const explicit = await loadResourceList(input);

    expect(canonical.view?.rows.map((row) => row.id)).toEqual(['provider-first', 'provider-second']);
    expect(explicit.view?.rows.map((row) => row.id)).toEqual(['explicit-first', 'explicit-second']);
  });

  it('maps declared controls into the list schema and drops unsupported query input', async () => {
    const fetcher = vi.fn(async (_input: RequestInfo | URL) => new Response(JSON.stringify({ ok: true, data: { items: [] } }), {
      status: 200,
      headers: { 'content-type': 'application/json' },
    }));
    const mappedRegistry: RegistryViewModel = {
      modules: [{
        ...registry.modules[0]!,
        resources: [{
          ...registry.modules[0]!.resources![0]!,
          listInputSchema: {
            type: 'object',
            properties: {
              limit: { type: 'integer' },
              filter: {
                type: 'object',
                properties: {
                  status: { type: 'string' },
                  enabled: { type: 'boolean' },
                  retries: { type: 'integer' },
                  cleared: { type: ['string', 'null'] },
                },
                additionalProperties: false,
              },
            },
            additionalProperties: false,
          },
          presentation: {
            query: { filters: [
              { field: 'status', inputPath: 'filter.status', label: 'Status', options: ['running', 'success'] },
              { field: 'enabled', inputPath: 'filter.enabled', options: [true, false] },
              { field: 'retries', inputPath: 'filter.retries' },
              { field: 'cleared', inputPath: 'filter.cleared', options: [null] },
            ] },
          },
        }],
      }],
    };

    const loaded = await loadResourceList({
      fetcher,
      url: new URL('https://console.example.test/modules/examplefn/records?q=ignored&status=running&enabled=false&retries=3&cleared=null&limit=25&unsupported=value'),
      registry: mappedRegistry,
      moduleId: 'examplefn',
      resourceId: 'records',
    });

    const requested = new URL(String(fetcher.mock.calls[0]![0]), 'https://console.example.test');
    expect(requested.searchParams.get('filter')).toBe(JSON.stringify({
      status: 'running', enabled: false, retries: 3, cleared: null,
    }));
    expect(requested.searchParams.get('limit')).toBe('25');
    expect(requested.searchParams.has('q')).toBe(false);
    expect(requested.searchParams.has('unsupported')).toBe(false);
    expect(loaded.view?.searchEnabled).toBe(false);
    expect(loaded.view?.filters).toEqual(expect.arrayContaining([
      { field: 'status', label: 'Status', value: 'running', options: ['running', 'success'] },
      { field: 'enabled', label: 'Enabled', value: 'false', options: [true, false] },
      { field: 'retries', label: 'Retries', value: '3', options: undefined },
      { field: 'cleared', label: 'Cleared', value: 'null', options: [null] },
    ]));
  });

  it('builds parent-bound related resource links from generic detail records', async () => {
    const contextualRegistry: RegistryViewModel = {
      modules: [{
        id: 'cifn',
        name: 'CiFn',
        description: 'CI resources.',
        href: '/modules/cifn',
        enabled: true,
        resources: [
          {
            id: 'runs', resourceId: 'runs', sourceModuleId: 'cifn', label: 'Runs', href: '/modules/cifn/runs',
            detailApiHref: '/api/admin/v1/modules/cifn/runs/:id', detailIdInput: 'id',
          },
          {
            id: 'jobs', resourceId: 'jobs', sourceModuleId: 'cifn', label: 'Jobs', href: '/modules/cifn/jobs',
            presentation: {
              parent: { resourceId: 'runs', bindings: [{ sourceField: 'runId', queryField: 'runId' }] },
            },
          },
          {
            id: 'artifacts', resourceId: 'artifacts', sourceModuleId: 'cifn', label: 'Artifacts', href: '/modules/cifn/artifacts',
            presentation: {
              parent: { resourceId: 'runs', bindings: [{ sourceField: 'runId', queryField: 'runId' }] },
            },
          },
        ],
      }],
    };
    const fetcher = vi.fn(async () => new Response(JSON.stringify({
      ok: true,
      data: { item: { runId: 'run_1', status: 'running' } },
    }), { status: 200, headers: { 'content-type': 'application/json' } }));

    const loaded = await loadResourceDetail({
      fetcher,
      url: new URL('https://console.example.test/modules/cifn/runs/run_1?environmentId=env_1'),
      registry: contextualRegistry,
      moduleId: 'cifn',
      resourceId: 'runs',
      identity: 'run_1',
    });

    expect(loaded.view?.related).toEqual([
      expect.objectContaining({ resourceId: 'jobs', href: '/modules/cifn/jobs?runId=run_1&environmentId=env_1' }),
      expect.objectContaining({ resourceId: 'artifacts', href: '/modules/cifn/artifacts?runId=run_1&environmentId=env_1' }),
    ]);
  });

  it('binds required action inputs that are present on each canonical row', () => {
    const rows = normalizeAdminResourceRows(
      [{ id: 'artifact_1', runId: 'run_1', name: 'report.zip' }],
      [{ key: 'name', label: 'Artifact' }],
      {
        id: 'artifacts', label: 'Artifacts', href: '/modules/cifn/artifacts',
        actions: [{
          id: 'cifn.artifacts.download-artifact', label: 'Download', targetIdInput: 'id',
          inputSchema: {
            type: 'object', properties: { id: { type: 'string' }, runId: { type: 'string' } },
            required: ['id', 'runId'], additionalProperties: false,
          },
        }],
      },
    );

    expect(rows[0]?.actions?.[0]?.input).toEqual({ id: 'artifact_1', runId: 'run_1' });
  it('fails startup when enabled mutations lack required infrastructure while shell-only installs work', () => {
    const capability = manifest({ destructive: true });
    const adapter = createAdminCapabilityAdapter(capability, { [capability.operations[0]!.id]: async () => ({ ok: true as const, data: { accepted: true } }) });
    expect(() => createSuperConsole({ adapters: [adapter], enabledModules: ['examplefn'], auth: auth(), shellPolicy: { authorize: () => true } })).toThrow(/audit sink/);
    expect(() => createSuperConsole({ adapters: [adapter], enabledModules: ['examplefn'], auth: auth(), shellPolicy: { authorize: () => true }, audit: new MemoryAdminAuditSink() })).toThrow(/idempotency store/);
    expect(() => createSuperConsole({ adapters: [adapter], enabledModules: ['examplefn'], auth: auth(), shellPolicy: { authorize: () => true }, audit: new MemoryAdminAuditSink(), idempotency: new MemoryAdminIdempotencyStore() })).toThrow(/confirmation issuer and verifier/);
    expect(() => createSuperConsole({
      adapters: [adapter],
      enabledModules: ['examplefn'],
      auth: { ...auth(), authorizeMutation: undefined },
      shellPolicy: { authorize: () => true },
      audit: new MemoryAdminAuditSink(),
      idempotency: new MemoryAdminIdempotencyStore(),
      confirmation: { issue: async () => ({ token: 'bound', expiresAt: new Date(Date.now() + 60_000).toISOString() }), verify: async () => true },
    })).toThrow(/mutation authorization/);
    expect(() => createSuperConsole({ adapters: [], enabledModules: [], auth: auth(), shellPolicy: { authorize: () => true } })).not.toThrow();
    expect(() => createSuperConsole({ adapters: [], enabledModules: [], auth: auth() } as never)).toThrow(/shell authorization policy/);
  });

  it('issues input-bound confirmation only after input/permission/policy checks and verifies it on dispatch', async () => {
    const { console, confirmation, handler } = installation({ destructive: true, permissions: ['examplefn.records.delete'] });
    const invalid = await console.handle(request('/api/admin/v1/confirmations', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ operationId: 'examplefn.records.delete', input: {} }) }));
    expect(invalid.status).toBe(400);
    const issued = await console.handle(request('/api/admin/v1/confirmations', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ operationId: 'examplefn.records.delete', input: { id: 'record_1' } }) }));
    expect(issued.status).toBe(201);
    expect(await issued.json()).toMatchObject({ ok: true as const, data: { token: 'bound-token', expiresAt: expect.any(String) } });
    expect(confirmation.issue).toHaveBeenCalledWith(expect.objectContaining({ operationId: 'examplefn.records.delete', input: { id: 'record_1' }, context: expect.objectContaining({ scope }) }));
    const executed = await console.handle(request('/api/admin/v1/modules/examplefn/records/record_1', {
      method: 'DELETE',
      headers: { 'idempotency-key': 'idem_1', 'x-admin-confirmation': 'bound-token' },
    }));
    expect(executed.status).toBe(200);
    expect(handler).toHaveBeenCalledTimes(1);
    expect(confirmation.verify).toHaveBeenCalled();
  });

  it('returns 405/OPTIONS/HEAD semantics instead of route ambiguity', async () => {
    const { console } = installation();
    expect((await console.handle(request('/api/admin/v1/registry', { method: 'POST' }))).status).toBe(405);
    const options = await console.handle(request('/api/admin/v1/registry', { method: 'OPTIONS' }));
    expect(options.status).toBe(204);
    expect(options.headers.get('allow')).toContain('GET');
    const head = await console.handle(request('/api/admin/v1/registry', { method: 'HEAD' }));
    expect(head.status).toBe(200);
    expect(await head.text()).toBe('');
    const resourceHead = await console.handle(request('/api/admin/v1/modules/examplefn/records', { method: 'HEAD' }));
    expect(resourceHead.status).toBe(200);
    expect(await resourceHead.text()).toBe('');
  });

  it('authorization-gates OpenAPI capability enumeration', async () => {
    const capability = manifest();
    const console = createSuperConsole({
      adapters: [createAdminCapabilityAdapter(capability, { 'examplefn.records.list': async () => ({ ok: true as const, data: { items: [] } }) })],
      enabledModules: ['examplefn'],
      auth: auth(),
      shellPolicy: { authorize: ({ surface }) => surface !== 'api' },
    });
    const result = await console.handle(request('/api/admin/v1/openapi.json'));
    expect(result.status).toBe(403);
    expect(JSON.stringify(await result.json())).not.toContain('examplefn.records.list');
  });

  it('projects only internal console hrefs from provider-neutral overview and search services', async () => {
    const searchManifest = manifest();
    const console = createSuperConsole({
      adapters: [createAdminCapabilityAdapter(searchManifest, { 'examplefn.records.list': async () => ({ ok: true as const, data: { items: [] } }) })],
      enabledModules: ['examplefn'],
      auth: auth(),
      shellPolicy: { authorize: () => true },
      overview: { read: async () => ({ alerts: [{ id: 'safe', href: '/modules/examplefn/records' }, { id: 'external', href: 'https://evil.example/' }, { id: 'script', href: 'javascript:alert(1)' }] }) },
