      const leftKey = `${left.getAttribute(PART)}:${left.getAttribute(INSTANCE) ?? ''}`;
      const rightKey = `${right.getAttribute(PART)}:${right.getAttribute(INSTANCE) ?? ''}`;
      return leftKey.localeCompare(rightKey);
