      sequence,
      name: action.name,
      arguments: action.arguments.map((value) => toSemanticJson(value)),
      observed: changed.length > 0 || runtime.callbacks.length > callbackCount,
    });
    checkpoints.push(next);
    previous = next;
  }
  return { actions, checkpoints };
}

function emptyResources() {
  return {
    listener: 0,
    observer: 0,
    timer: 0,
    animationFrame: 0,
    layer: 0,
    focusScope: 0,
    modalLock: 0,
    positioner: 0,
    portal: 0,
    presence: 0,
    formBridge: 0,
    liveRegion: 0,
    modality: 0,
    total: 0,
  };
}

export function capturePhase14Cleanup(token, bridge, scheduler) {
  const counters = bridge.getLifecycleCounters();
