/**
 * Workflow status
 */
export enum WorkflowStatus {
  Enabled = 'enabled',
  Disabled = 'disabled',
  Draft = 'draft',
}

/**
 * Workflow execution status
 */
export enum WorkflowExecutionStatus {
  Pending = 'pending',
  Running = 'running',
  Completed = 'completed',
  Failed = 'failed',
  Cancelled = 'cancelled',
}

/**
 * Workflow definition stored in database
 */
export interface Workflow {
  id: string;
  userId: string;
