  metadata?: Record<string, any>;
  createdAt: Date;
  updatedAt: Date;
}

/**
 * Workflow definition structure
 */
export interface WorkflowDefinition {
  trigger: WorkflowTrigger;
  steps: WorkflowStep[];
  errorHandlers?: WorkflowErrorHandler[];
}

/**
 * Workflow trigger configuration
 */
export interface WorkflowTrigger {
  provider: string;
  event: string;
  filter?: WorkflowCondition;
}

export type WorkflowAction = (context: WorkflowContext) => Promise<any>;
export type WorkflowCondition = string | ((context: WorkflowContext) => boolean);
export type WorkflowErrorHandlerFn = (
  error: Error,
  context: WorkflowContext
) => Promise<void>;

/** Runtime implementations for serializable workflow references. */
export interface WorkflowRuntimeRegistry {
  actions?: Record<string, WorkflowAction>;
  conditions?: Record<string, Exclude<WorkflowCondition, string>>;
  errorHandlers?: Record<string, WorkflowErrorHandlerFn>;
}

/**
 * Workflow step types
 */
export type WorkflowStep =
  | ActionStep
  | FilterStep
  | BranchStep
  | ParallelStep
  | DelayStep;

export interface ActionStep {
  type: 'action';
  id: string;
  action: string | WorkflowAction;
}

export interface FilterStep {
  type: 'filter';
  id: string;
  condition: WorkflowCondition;
}

export interface BranchStep {
  type: 'branch';
  id: string;
  condition: WorkflowCondition;
  then: WorkflowStep[];
  else?: WorkflowStep[];
}

export interface ParallelStep {
  type: 'parallel';
  id: string;
  actions: Array<string | WorkflowAction>;
}

export interface DelayStep {
  type: 'delay';
  id: string;
  duration: number;
  unit?: 'ms' | 'seconds' | 'minutes' | 'hours' | 'days';
}

/**
 * Workflow execution context
 */
export interface WorkflowContext {
  workflowId: string;
  executionId: string;
  userId: string;
  trigger: {
    provider: string;
    event: string;
    payload: any;
  };
  data: Record<string, any>;
  metadata?: Record<string, any>;
}

/**
 * Error handler
 */
export interface WorkflowErrorHandler {
  stepId?: string;
  handler: string | WorkflowErrorHandlerFn;
}

/**
 * Workflow execution record
 */
export interface WorkflowExecution {
  id: string;
  workflowId: string;
  status: WorkflowExecutionStatus;
  input?: any;
  output?: any;
  error?: string;
  durationMs?: number;
  startedAt: Date;
  completedAt?: Date;
}

/**
 * Workflow statistics
 */
export interface WorkflowStats {
  totalExecutions: number;
  successfulExecutions: number;
  failedExecutions: number;
  successRate: number;
  avgDuration: number;
  lastExecutedAt?: Date;
}

/**
 * List workflows options
 */
export interface ListWorkflowsOptions {
  userId?: string;
  status?: WorkflowStatus;
  provider?: string;
}
import type {
  Workflow,
