        message: 'Super Console has not been composed for this server process.',
        status: 503,
      },
    }), {
      status: 503,
      headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' },
    });
  }
  return console.handle(request);
}
